import { fireEvent, render, waitFor } from '@testing-library/react'
import React from 'react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { logger } from '@/utils/logger'

describe('audio & Memory Testing for Gaming', () => {
  describe('audio System Tests', () => {
    let audioPlaySpy: any
    let audioStopSpy: any

    beforeEach(() => {
      // Mock Web Audio API
      globalThis.AudioContext = vi.fn(() => ({
        createOscillator: vi.fn(() => ({
          connect: vi.fn(),
          start: vi.fn(),
          stop: vi.fn(),
          frequency: { value: 440 },
        })),
        createGain: vi.fn(() => ({
          connect: vi.fn(),
          gain: { value: 1 },
        })),
        createBuffer: vi.fn(),
        createTexture: vi.fn(),
        destination: {},
      })) as any

      // Mock Howler.js
      audioPlaySpy = vi.fn()
      audioStopSpy = vi.fn()

      globalThis.Howl = vi.fn(() => ({
        play: audioPlaySpy,
        stop: audioStopSpy,
        volume: vi.fn(),
        duration: vi.fn(() => 1000),
        playing: vi.fn(() => false),
      })) as any
    })

    afterEach(() => {
      vi.restoreAllMocks()
    })

    it('plays dice roll sound with correct timing', async () => {
      const mockDiceRoller = () => {
        const handleRoll = () => {
          // Simulate dice roll with sound
          const sound = new (globalThis.Howl as any)({
            src: ['dice-roll.mp3'],
          })
          sound.play()
        }

        return (
          <button type='button' onClick={handleRoll} data-testid='roll-button'>
            Roll Dice
          </button>
        )
      }

      const { getByTestId } = render(mockDiceRoller())

      fireEvent.click(getByTestId('roll-button'))

      expect(audioPlaySpy).toHaveBeenCalled()
      expect(audioPlaySpy).toHaveBeenCalledTimes(1)
    })

    it('handles multiple simultaneous audio sources', async () => {
      const mockAudioManager = () => {
        const handleMultipleSounds = () => {
          // Simulate background music + sound effects
          const bgMusic = new (globalThis.Howl as any)({
            src: ['bg-music.mp3'],
          })
          const diceSound = new (globalThis.Howl as any)({ src: ['dice.mp3'] })
          const successSound = new (globalThis.Howl as any)({
            src: ['success.mp3'],
          })

          bgMusic.play()
          diceSound.play()
          successSound.play()
        }

        return (
          <button type='button' onClick={handleMultipleSounds} data-testid='multi-audio'>
            Play Multiple
          </button>
        )
      }

      const { getByTestId } = render(mockAudioManager())

      fireEvent.click(getByTestId('multi-audio'))

      expect(audioPlaySpy).toHaveBeenCalledTimes(3)
    })

    it('respects user audio preferences', async () => {
      const MockAudioSettings = () => {
        const [audioEnabled, setAudioEnabled] = React.useState(false)

        const handleToggleAudio = () => {
          setAudioEnabled(!audioEnabled)
          localStorage.setItem('audioEnabled', String(!audioEnabled))
        }

        const handlePlay = () => {
          if (audioEnabled) {
            const sound = new (globalThis.Howl as any)({ src: ['test.mp3'] })
            sound.play()
          }
        }

        return (
          <div>
            <button type='button' onClick={handleToggleAudio} data-testid='audio-toggle'>
              {audioEnabled ? 'Disable' : 'Enable'} Audio
            </button>
            <button type='button' onClick={handlePlay} data-testid='play-sound'>
              Play Sound
            </button>
          </div>
        )
      }

      const { getByTestId } = render(<MockAudioSettings />)

      // Initially audio is disabled
      fireEvent.click(getByTestId('play-sound'))
      expect(audioPlaySpy).not.toHaveBeenCalled()

      // Enable audio
      fireEvent.click(getByTestId('audio-toggle'))
      fireEvent.click(getByTestId('play-sound'))
      expect(audioPlaySpy).toHaveBeenCalled()
    })

    it('handles audio loading errors gracefully', async () => {
      const mockErrorHandler = () => {
        const handlePlayWithError = () => {
          const sound = new (globalThis.Howl as any)({
            src: ['nonexistent.mp3'],
            onloaderror: (id: any, error: any) => {
              logger.info('Audio load error handled:', error)
            },
          })
          sound.play()
        }

        return (
          <button type='button' onClick={handlePlayWithError} data-testid='error-audio'>
            Play Broken Audio
          </button>
        )
      }

      // Mock console.log to verify error handling
      vi.spyOn(logger, 'info')

      const { getByTestId } = render(mockErrorHandler())
      fireEvent.click(getByTestId('error-audio'))

      // Should still attempt to play (graceful degradation)
      expect(audioPlaySpy).toHaveBeenCalled()
    })
  })

  describe('memory Management Tests', () => {
    it('cleans up event listeners on component unmount', async () => {
      const addEventListenerSpy = vi.spyOn(document, 'addEventListener')
      const removeEventListenerSpy = vi.spyOn(document, 'removeEventListener')

      const MockKeyboardComponent = () => {
        React.useEffect(() => {
          const handleKeydown = (e: KeyboardEvent) => {
            if (e.key === 'r') {
              logger.info('Roll dice shortcut')
            }
          }

          document.addEventListener('keydown', handleKeydown)

          return () => {
            document.removeEventListener('keydown', handleKeydown)
          }
        }, [])

        return <div>Keyboard Handler</div>
      }

      const { unmount } = render(<MockKeyboardComponent />)

      expect(addEventListenerSpy).toHaveBeenCalledWith(
        'keydown',
        expect.any(Function),
      )

      unmount()

      expect(removeEventListenerSpy).toHaveBeenCalledWith(
        'keydown',
        expect.any(Function),
      )

      addEventListenerSpy.mockRestore()
      removeEventListenerSpy.mockRestore()
    })

    it('prevents memory leaks in animation loops', async () => {
      const cancelAnimationFrameSpy = vi.spyOn(window, 'cancelAnimationFrame')
      const requestAnimationFrameSpy = vi.spyOn(window, 'requestAnimationFrame')

      const MockAnimationComponent = () => {
        React.useEffect(() => {
          let animationId: number

          const animate = () => {
            // Simulate dice rolling animation
            animationId = requestAnimationFrame(animate)
          }

          animate()

          return () => {
            if (animationId) {
              cancelAnimationFrame(animationId)
            }
          }
        }, [])

        return <div>Animated Component</div>
      }

      const { unmount } = render(<MockAnimationComponent />)

      expect(requestAnimationFrameSpy).toHaveBeenCalled()

      unmount()

      expect(cancelAnimationFrameSpy).toHaveBeenCalled()

      cancelAnimationFrameSpy.mockRestore()
      requestAnimationFrameSpy.mockRestore()
    })

    it('manages large datasets efficiently', async () => {
      const MockLargeDataComponent = () => {
        const [data, setData] = React.useState<any[]>([])

        React.useEffect(() => {
          // Simulate loading large character/campaign data
          const largeDataset = Array.from({ length: 10000 })
            .fill(0)
            .map((_, i) => ({
              id: i,
              name: `Character ${i}`,
              stats: {
                hp: Math.floor(Math.random() * 20) + 1,
                level: Math.floor(Math.random() * 10) + 1,
              },
            }))

          setData(largeDataset)

          // Cleanup function
          return () => {
            setData([])
          }
        }, [])

        return <div>Loaded {data.length} items</div>
      }

      const { unmount, getByText } = render(<MockLargeDataComponent />)

      await waitFor(() => {
        expect(getByText('Loaded 10000 items')).toBeTruthy()
      })

      // Verify data is loaded
      expect(getByText('Loaded 10000 items')).toBeTruthy()

      unmount()

      // Memory should be freed (we can't directly test this, but the cleanup should run)
    })

    it('handles WebGL context cleanup', async () => {
      const mockCanvas = {
        getContext: vi.fn(() => ({
          createBuffer: vi.fn(),
          createTexture: vi.fn(),
          deleteBuffer: vi.fn(),
          deleteTexture: vi.fn(),
          deleteProgram: vi.fn(),
          deleteShader: vi.fn(),
          getExtension: vi.fn(() => ({ loseContext: vi.fn() })),
        })),
      }

      const MockWebGLComponent = () => {
        React.useEffect(() => {
          const canvas = mockCanvas as any
          const gl = canvas.getContext('webgl')

          // Simulate creating WebGL resources
          const buffer = gl.createBuffer()
          const texture = gl.createTexture()

          return () => {
            // Cleanup WebGL resources
            if (buffer) gl.deleteBuffer(buffer)
            if (texture) gl.deleteTexture(texture)

            // Lose context to free memory
            const loseContext = gl.getExtension('WEBGL_lose_context')
            if (loseContext) loseContext.loseContext()
          }
        }, [])

        return <div>WebGL Component</div>
      }

      const { unmount } = render(<MockWebGLComponent />)

      expect(mockCanvas.getContext).toHaveBeenCalledWith('webgl')

      unmount()

      // Verify cleanup methods would be called
      // (In real implementation, these would actually clean up GPU resources)
    })
  })

  describe('long Gaming Session Simulation', () => {
    it('maintains performance over extended play', async () => {
      // Simulate a 2-hour gaming session with frequent state updates
      const sessionActions = []

      for (let i = 0; i < 1000; i++) {
        sessionActions.push({
          type: 'dice_roll',
          result: Math.floor(Math.random() * 20) + 1,
          timestamp: Date.now() + i * 100,
        })

        if (i % 10 === 0) {
          sessionActions.push({
            type: 'hp_change',
            delta: Math.floor(Math.random() * 10) - 5,
            timestamp: Date.now() + i * 100,
          })
        }

        if (i % 50 === 0) {
          sessionActions.push({
            type: 'level_up',
            newLevel: Math.floor(i / 50) + 1,
            timestamp: Date.now() + i * 100,
          })
        }
      }

      // Test that the action history doesn't grow unbounded
      expect(sessionActions.length).toBe(1120) // 1000 rolls + 100 HP + 20 level ups

      // In a real implementation, old actions should be cleaned up
      const cutoffTime = Date.now() - 1800000 // 30 minutes ago
      const recentActions = sessionActions.filter(
        (action) => action.timestamp > cutoffTime,
      )

      expect(recentActions.length).toBeLessThanOrEqual(sessionActions.length)
    })
  })
})

/**
 * Context-Aware System for ZimboMate V2
 * Provides intelligent suggestions based on character state, game context, and current situation
 * Phase 4C: Desktop Power Features - Smart Integration System
 */

import { AnimatePresence, motion } from 'framer-motion'
import {
  AlertTriangle,
  BookOpen,
  ChevronRight,
  Clock,
  Heart,
  Lightbulb,
  Shield,
  Sparkles,
  Target,
  TrendingUp,
  X,
  Zap,
} from 'lucide-react'
import React, { useMemo, useState } from 'react'
import { getEffectiveModifier, shouldLevelUp } from '../../models/Character'
import { useCharacterStore } from '../../stores/characterStore'
import { useGameStateStore } from '../../stores/gameStateStore'
import { useSessionStore } from '../../stores/sessionStore'
import { Badge, Button, Card, CardContent } from '../ui'

// Suggestion types
export type SuggestionType =
  | 'move'
  | 'equipment'
  | 'health'
  | 'resource'
  | 'advancement'
  | 'tactical'
  | 'roleplay'
  | 'warning'

export type SuggestionPriority = 'low' | 'medium' | 'high' | 'critical'

export interface ContextSuggestion {
  id: string
  type: SuggestionType
  priority: SuggestionPriority
  title: string
  description: string
  reason: string
  action?: {
    label: string
    onClick: () => void
  }
  dismissible: boolean
  timestamp: Date
}

interface ContextAwareSystemProps {
  characterId?: string
  context?:
    | 'character'
    | 'dice'
    | 'moves'
    | 'equipment'
    | 'session'
    | 'campaign'
  maxSuggestions?: number
  showDismissed?: boolean
  compact?: boolean
}

export const ContextAwareSystem: React.FC<ContextAwareSystemProps> = ({
  characterId,
  context = 'character',
  maxSuggestions = 5,
  showDismissed = false,
  compact = false,
}) => {
  const { getActiveCharacter, getCharacter, healCharacter, levelUpCharacter } =
    useCharacterStore()
  const { rollHistory, combat, currentSession } = useSessionStore()
  const { environment } = useGameStateStore()

  const [dismissedSuggestions, setDismissedSuggestions] = useState<Set<string>>(
    new Set(),
  )
  const [expandedSuggestion, setExpandedSuggestion] = useState<string | null>(
    null,
  )

  // Get the target character
  const character = characterId
    ? getCharacter(characterId)
    : getActiveCharacter()

  // Generate context-aware suggestions
  const suggestions = useMemo(() => {
    if (!character) return []

    const suggestions: ContextSuggestion[] = []
    const now = new Date()

    // Health-related suggestions
    if (character.hp.current <= character.hp.max * 0.25) {
      suggestions.push({
        id: 'critical-health',
        type: 'health',
        priority: 'critical',
        title: 'Critical Health!',
        description: `${character.name} has only ${character.hp.current}/${character.hp.max} HP remaining.`,
        reason: 'Character is in immediate danger',
        action: {
          label: 'Heal Character',
          onClick: () =>
            healCharacter(character.id, Math.ceil(character.hp.max * 0.5)),
        },
        dismissible: false,
        timestamp: now,
      })
    } else if (character.hp.current <= character.hp.max * 0.5) {
      suggestions.push({
        id: 'low-health',
        type: 'health',
        priority: 'high',
        title: 'Low Health',
        description: `Consider healing or resting. Current HP: ${character.hp.current}/${character.hp.max}`,
        reason: 'Character health is below 50%',
        action: {
          label: 'Heal Character',
          onClick: () =>
            healCharacter(character.id, Math.ceil(character.hp.max * 0.25)),
        },
        dismissible: true,
        timestamp: now,
      })
    }

    // Advancement suggestions
    if (shouldLevelUp(character)) {
      suggestions.push({
        id: 'level-up-ready',
        type: 'advancement',
        priority: 'high',
        title: 'Ready to Level Up!',
        description: `${character.name} has enough XP to advance to level ${character.level + 1}.`,
        reason: `Has ${character.xp} XP, needs ${character.level + 7}`,
        action: {
          label: 'Level Up',
          onClick: () => levelUpCharacter(character.id),
        },
        dismissible: false,
        timestamp: now,
      })
    }

    // Load/encumbrance suggestions
    if (character.load.current > character.load.max) {
      suggestions.push({
        id: 'overencumbered',
        type: 'warning',
        priority: 'high',
        title: 'Overencumbered!',
        description: `Carrying ${character.load.current}/${character.load.max} load. Take -1 ongoing until fixed.`,
        reason: 'Load exceeds maximum capacity',
        dismissible: true,
        timestamp: now,
      })
    } else if (character.load.current >= character.load.max * 0.8) {
      suggestions.push({
        id: 'heavy-load',
        type: 'equipment',
        priority: 'medium',
        title: 'Heavy Load',
        description: `Nearing max load (${character.load.current}/${character.load.max}). Consider dropping items.`,
        reason: 'Load is at 80% capacity',
        dismissible: true,
        timestamp: now,
      })
    }

    // Debility warnings
    const activeDebilities = Object.entries(character.debilities).filter(
      ([_, active]) => active,
    )
    if (activeDebilities.length > 0) {
      suggestions.push({
        id: 'active-debilities',
        type: 'warning',
        priority: 'high',
        title: 'Active Debilities',
        description: `${activeDebilities.map(([name]) => name).join(', ')} affecting dice rolls.`,
        reason: 'Debilities reduce attribute modifiers',
        dismissible: true,
        timestamp: now,
      })
    }

    // Combat-specific suggestions
    if (combat.isActive && context === 'dice') {
      const recentRolls = rollHistory.slice(0, 3)
      const recentFailures = recentRolls.filter(
        (roll) => roll.result === 'failure',
      ).length

      if (recentFailures >= 2) {
        suggestions.push({
          id: 'combat-struggling',
          type: 'tactical',
          priority: 'medium',
          title: 'Consider Different Tactics',
          description:
            'Recent failures suggest trying a different approach or using Aid/Interfere.',
          reason: `${recentFailures} failures in last 3 rolls`,
          dismissible: true,
          timestamp: now,
        })
      }

      // Suggest defensive moves if health is low
      if (character.hp.current <= character.hp.max * 0.4) {
        suggestions.push({
          id: 'combat-defensive',
          type: 'tactical',
          priority: 'high',
          title: 'Consider Defensive Actions',
          description:
            'Low health in combat - consider Defend or retreating to safety.',
          reason: 'Low health during active combat',
          dismissible: true,
          timestamp: now,
        })
      }
    }

    // Move suggestions based on context
    if (context === 'moves') {
      // Suggest contextual moves based on character state
      if (
        character.class === 'Wizard' &&
        character.hp.current <= character.hp.max * 0.3
      ) {
        suggestions.push({
          id: 'wizard-defensive-spells',
          type: 'move',
          priority: 'medium',
          title: 'Defensive Spells Available',
          description: 'Consider casting Shield or other protective spells.',
          reason: 'Wizard with low health should use defensive magic',
          dismissible: true,
          timestamp: now,
        })
      }

      if (
        character.class === 'Cleric' &&
        character.hp.current <= character.hp.max * 0.6
      ) {
        suggestions.push({
          id: 'cleric-healing',
          type: 'move',
          priority: 'medium',
          title: 'Healing Magic Available',
          description: 'Use Cure Light Wounds or other healing spells.',
          reason: 'Cleric should consider self-healing',
          dismissible: true,
          timestamp: now,
        })
      }
    }

    // Equipment suggestions
    if (context === 'equipment') {
      // Suggest equipment optimization based on class and stats
      const strMod = getEffectiveModifier(
        'STR',
        character.attributes,
        character.debilities,
      )
      const dexMod = getEffectiveModifier(
        'DEX',
        character.attributes,
        character.debilities,
      )

      if (
        character.class === 'Fighter' &&
        strMod >= 2 &&
        character.load.current < character.load.max * 0.7
      ) {
        suggestions.push({
          id: 'fighter-heavy-armor',
          type: 'equipment',
          priority: 'low',
          title: 'Consider Heavier Armor',
          description:
            'High STR allows for better armor without encumbrance issues.',
          reason: `STR modifier is +${strMod}, load capacity available`,
          dismissible: true,
          timestamp: now,
        })
      }

      if (dexMod >= 2 && character.class === 'Thief') {
        suggestions.push({
          id: 'thief-ranged-weapons',
          type: 'equipment',
          priority: 'low',
          title: 'Ranged Weapons Recommended',
          description: 'High DEX makes ranged combat very effective.',
          reason: `DEX modifier is +${dexMod}`,
          dismissible: true,
          timestamp: now,
        })
      }
    }

    // Session-specific suggestions
    if (currentSession && context === 'session') {
      const sessionDuration = Date.now() - currentSession.startTime.getTime()
      const hoursPlayed = sessionDuration / (1000 * 60 * 60)

      if (hoursPlayed > 3 && character.hp.current === character.hp.max) {
        suggestions.push({
          id: 'long-session-rest',
          type: 'roleplay',
          priority: 'low',
          title: 'Consider Taking a Rest',
          description:
            'Long session - characters might want to rest and recover.',
          reason: `Session running for ${Math.floor(hoursPlayed)} hours`,
          dismissible: true,
          timestamp: now,
        })
      }
    }

    // Environmental suggestions
    if (
      environment.lighting === 'dark' &&
      character.race !== 'Elf' &&
      character.race !== 'Dwarf'
    ) {
      suggestions.push({
        id: 'darkness-penalty',
        type: 'warning',
        priority: 'medium',
        title: 'Darkness Affects Vision',
        description:
          'Poor lighting may impose penalties on sight-based actions.',
        reason: 'Current environment is dark',
        dismissible: true,
        timestamp: now,
      })
    }

    // XP opportunity suggestions
    const recentFailures = rollHistory
      .slice(0, 5)
      .filter((roll) => roll.result === 'failure').length
    if (recentFailures === 0 && rollHistory.length >= 5) {
      suggestions.push({
        id: 'xp-opportunity',
        type: 'roleplay',
        priority: 'low',
        title: 'XP Opportunity',
        description:
          'No recent failures - consider taking risks for XP and story development.',
        reason: 'No failures in last 5 rolls',
        dismissible: true,
        timestamp: now,
      })
    }

    // Sort by priority and filter dismissed
    return suggestions
      .sort((a, b) => {
        const priorityOrder = { critical: 4, high: 3, medium: 2, low: 1 }
        return priorityOrder[b.priority] - priorityOrder[a.priority]
      })
      .filter(
        (suggestion) =>
          showDismissed || !dismissedSuggestions.has(suggestion.id),
      )
      .slice(0, maxSuggestions)
  }, [
    character,
    context,
    rollHistory,
    combat,
    currentSession,
    environment,
    dismissedSuggestions,
    showDismissed,
    maxSuggestions,
    healCharacter,
    levelUpCharacter,
  ])

  const handleDismiss = (suggestionId: string) => {
    setDismissedSuggestions((prev) => new Set([...prev, suggestionId]))
  }

  const getSuggestionIcon = (type: SuggestionType) => {
    switch (type) {
      case 'move':
        return BookOpen
      case 'equipment':
        return Shield
      case 'health':
        return Heart
      case 'resource':
        return Zap
      case 'advancement':
        return TrendingUp
      case 'tactical':
        return Target
      case 'roleplay':
        return Sparkles
      case 'warning':
        return AlertTriangle
      default:
        return Lightbulb
    }
  }

  const getPriorityColor = (priority: SuggestionPriority) => {
    switch (priority) {
      case 'critical':
        return 'var(--destructive)'
      case 'high':
        return 'var(--chart-4)'
      case 'medium':
        return 'var(--primary)'
      case 'low':
        return 'var(--muted-foreground)'
    }
  }

  if (!character || suggestions.length === 0) {
    return null
  }

  return (
    <Card variant='magical'>
      <CardContent>
        <div className='space-y-4'>
          <div className='flex items-center gap-2'>
            <Lightbulb className='text-primary' size={20} />
            <h3 className='font-display text-lg'>Smart Suggestions</h3>
            <Badge variant='secondary' size='sm'>
              {suggestions.length}
            </Badge>
          </div>

          <AnimatePresence>
            {suggestions.map((suggestion, index) => {
              const Icon = getSuggestionIcon(suggestion.type)
              const isExpanded = expandedSuggestion === suggestion.id

              return (
                <motion.div
                  key={suggestion.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  transition={{ duration: 0.3, delay: index * 0.1 }}
                >
                  <Card
                    variant='outline'
                    className={`cursor-pointer transition-all duration-200 ${
                      isExpanded ? 'ring-2' : 'hover:shadow-md'
                    }`}
                    style={{
                      ringColor: isExpanded
                        ? getPriorityColor(suggestion.priority)
                        : undefined,
                    }}
                    onClick={() =>
                      setExpandedSuggestion(isExpanded ? null : suggestion.id)
                    }
                  >
                    <CardContent>
                      <div className='flex items-start gap-3'>
                        <div
                          className='w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0'
                          style={{
                            backgroundColor: getPriorityColor(
                              suggestion.priority,
                            ),
                            opacity: 0.2,
                          }}
                        >
                          <Icon
                            size={16}
                            style={{
                              color: getPriorityColor(suggestion.priority),
                            }}
                          />
                        </div>

                        <div className='flex-1 min-w-0'>
                          <div className='flex items-center gap-2 mb-1'>
                            <h4 className='font-medium text-sm truncate'>
                              {suggestion.title}
                            </h4>
                            <Badge
                              variant={
                                suggestion.priority === 'critical'
                                  ? 'destructive'
                                  : 'secondary'
                              }
                              size='xs'
                            >
                              {suggestion.priority}
                            </Badge>
                          </div>

                          <p className='text-sm mb-2 text-muted-foreground'>
                            {suggestion.description}
                          </p>

                          <AnimatePresence>
                            {isExpanded && (
                              <motion.div
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                exit={{ opacity: 0, height: 0 }}
                                transition={{ duration: 0.2 }}
                                className='space-y-3'
                              >
                                <div
                                  className='text-xs p-2 rounded'
                                  style={{
                                    backgroundColor: 'var(--card)',
                                    color: 'var(--muted-foreground)',
                                  }}
                                >
