                                    </Button>
                                  )}

                                  {suggestion.dismissible && (
                                    <Button
                                      variant='ghost'
                                      size='xs'
                                      onClick={(e) => {
                                        e.stopPropagation()
                                        handleDismiss(suggestion.id)
                                      }}
