function createNPC(input: string): CreatedNPC {
  const id = Math.random().toString(36).substr(2, 9)

  if (input.toLowerCase().includes('merchant')) {
    return {
      id,
      name: 'Aldric Coinworth',
      appearance: 'A portly man with calculating eyes and fine clothes',
      drive: 'To profit from every transaction',
      quirk: 'Always counts coins twice',
      voice: 'Smooth and persuasive, with a slight wheeze',
      knows: 'Trade routes, valuable goods, local customs',
    }
  }

  return {
    id,
    name: input || 'Unnamed Person',
    appearance: 'An ordinary-looking individual',
    drive: 'To live their daily life',
    quirk: 'Has a memorable mannerism',
    voice: 'Speaks in a distinctive way',
    knows: 'Local gossip and common knowledge',
  }
}

function createMonster(input: string): CreatedMonster {
  const id = Math.random().toString(36).substr(2, 9)

  if (input.toLowerCase().includes('goblin')) {
    return {
      id,
      name: 'Goblin Raider',
      hp: 6,
      armor: 1,
      damage: '1d6',
      instinct: 'To raid and pillage',
      moves: [
        'Swarm with numbers',
        'Strike from shadows',
        'Flee when outnumbered',
      ],
    }
  }

  return {
    id,
    name: input || 'Unknown Creature',
    hp: 8,
    armor: 0,
    damage: '1d6',
    instinct: 'To survive',
    moves: ['Fight when cornered', 'Protect territory', 'Seek sustenance'],
  }
}

export const PlayTab: React.FC<PlayTabProps> = ({ className = '' }) => {
  const { getActiveCharacter } = useCharacterStore()
  const activeCharacter = getActiveCharacter()
  const deltaHistory = useChronicleStore((state) => state.deltaHistory)
  const clearDeltaLog = useChronicleStore((state) => state.clearDeltaLog)
  const recentDeltaHistory = useMemo(
    () => deltaHistory.slice(0, 5),
    [deltaHistory],
  )
  const [undoingBundleId, setUndoingBundleId] = useState<string | null>(null)
  const chronicleTextareaRef = useRef<HTMLTextAreaElement>(null)

  const {
    proposeEntryDeltas,
    applyDeltaBundle,
    isProposing,
    isApplyingBundle,
    lastProgressEvent,
    lastTelemetryEvent,
    settings,
    _updateSettings,
  } = useChronicleLLM()

  const handleUndoBundle = useCallback(
    async (bundleId: string) => {
      setUndoingBundleId(bundleId)
      try {
        const success = await undoChronicleBundle(bundleId)
        if (!success) {
          console.warn(`[chronicle] Unable to undo bundle ${bundleId}`)
          return
        }
        clearDeltaLog(bundleId)
      } catch (error) {
        console.error('[chronicle] Undo bundle failed', error)
      } finally {
        setUndoingBundleId(null)
      }
    },
    [clearDeltaLog],
  )

  // New state for Immersive Storyteller Mode
  const [activeTab, setActiveTab] = useState<ActiveTab>('chronicle')
  const [toolsSubTab, setToolsSubTab] = useState<ToolsSubTab>('items')
  const [characterPanelCollapsed, setCharacterPanelCollapsed] = useState(true)
  const [campaignVibe, setCampaignVibe] = useState<CampaignVibe>('fantasy')

  // Chronicle state
  const [chronicleText, setChronicleText] = useState('')
  const [chronicleEntries, setChronicleEntries] = useState<
    ChronicleEntryView[]
  >([])
  const entriesRef = useRef<ChronicleEntryView[]>([])
  const [pendingDiceContext, setPendingDiceContext] =
    useState<DiceRollContext | null>(null)

  useEffect(() => {
    entriesRef.current = chronicleEntries
  }, [chronicleEntries])

  // Tool creation state
  const [itemInput, setItemInput] = useState('')
  const [npcInput, setNpcInput] = useState('')
  const [monsterInput, setMonsterInput] = useState('')
  const [createdItems, setCreatedItems] = useState<CreatedItem[]>([])
  const [createdNPCs, setCreatedNPCs] = useState<CreatedNPC[]>([])
  const [createdMonsters, setCreatedMonsters] = useState<CreatedMonster[]>([])

  // Session management
  const [isSessionActive, _setIsSessionActive] = useState(false)
  const [sessionTime, _setSessionTime] = useState(0)

  // Chronicle automation helpers
  const updateEntry = useCallback(
    (
      entryId: string,
      updater:
        | Partial<ChronicleEntryView>
        | ((entry: ChronicleEntryView) => ChronicleEntryView),
    ) => {
      setChronicleEntries((prev) =>
        prev.map((entry) => {
          if (entry.id !== entryId) return entry
          if (typeof updater === 'function')
            return (
              updater as (entry: ChronicleEntryView) => ChronicleEntryView
            )(entry)
          return { ...entry, ...updater }
        }),
      )
    },
    [],
  )

  const resolveCharacterName = useCallback(
    (characterId?: string) => {
      if (
        !characterId ||
        characterId === '.' ||
        characterId === 'active_character'
      ) {
        return activeCharacter?.name ?? 'your character'
      }
      if (activeCharacter?.id && characterId === activeCharacter.id) {
        return activeCharacter.name
      }
      return characterId
    },
    [activeCharacter?.id, activeCharacter?.name],
  )

  const describeDeltaOperation = useCallback(
    (op: DeltaOperation) => {
      return formatDeltaOperation(op, resolveCharacterName)
    },
    [resolveCharacterName],
  )

  const buildSelectionMap = useCallback(
    (ops: DeltaOperation[], warnings: string[]) => {
      const selection: Record<number, boolean> = {}
      const hasWarnings = warnings.length > 0
      ops.forEach((op, index) => {
        const policy = settings?.autoApplyPolicy?.[op.type] ?? 'confirm'
        selection[index] = policy === 'auto' && !hasWarnings
      })
      return selection
    },
    [settings?.autoApplyPolicy],
  )

  const shouldAutoApplyBundle = useCallback(
    (
      bundle: ProposedDeltaBundle,
      selection: Record<number, boolean>,
      warnings: string[],
    ) => {
      if (warnings.length > 0) return false
      if (bundle.ops.length === 0) return false
      return bundle.ops.every((_, index) => selection[index])
    },
    [],
  )

  const toggleOperationSelection = useCallback(
    (entryId: string, index: number, checked: boolean) => {
      updateEntry(entryId, (entry) => ({
        ...entry,
        selection: { ...entry.selection, [index]: checked },
        status: entry.status === 'applied' ? entry.status : 'ready',
        errorMessage: undefined,
      }))
    },
    [updateEntry],
  )

  const applyBundleForEntry = useCallback(
    async (entryId: string, { auto }: { auto?: boolean } = {}) => {
      const entrySnapshot = entriesRef.current.find(
        (entry) => entry.id === entryId,
      )
      if (!entrySnapshot || !entrySnapshot.bundle) {
        updateEntry(entryId, (entry) => ({
          ...entry,
          status: 'error',
          errorMessage: 'No delta bundle available for this entry.',
        }))
        return
      }

      const selectedIndices = Object.entries(entrySnapshot.selection)
        .filter(([, value]) => value)
        .map(([index]) => Number(index))
        .sort((a, b) => a - b)

      if (selectedIndices.length === 0) {
        updateEntry(entryId, (entry) => ({
          ...entry,
          status: 'ready',
          errorMessage: 'Select at least one update to apply.',
        }))
        return
      }

      updateEntry(entryId, (entry) => ({
        ...entry,
        status: 'applying',
        errorMessage: undefined,
      }))

      try {
        const result = await applyDeltaBundle({
          bundle: entrySnapshot.bundle,
          autoApply: Boolean(auto),
          selectedOpIndices: selectedIndices,
        })

        updateEntry(entryId, (entry) => ({
          ...entry,
          status: 'applied',
          result,
          errorMessage: undefined,
        }))
      } catch (error) {
        const message =
          error instanceof Error ? error.message : 'Failed to apply bundle.'
        updateEntry(entryId, (entry) => ({
          ...entry,
          status: 'error',
          errorMessage: message,
        }))
      }
    },
    [applyDeltaBundle, updateEntry],
  )

  const addChronicleEntry = useCallback(
    async (rawText: string) => {
      const trimmed = rawText.trim()
      if (!trimmed) return

      const entryId =
        typeof crypto !== 'undefined' && 'randomUUID' in crypto
          ? crypto.randomUUID()
          : Math.random().toString(36).slice(2, 10)
      const createdAt = new Date()

      const baseEntry: ChronicleEntryView = {
        id: entryId,
        rawText: trimmed,
        createdAt,
        warnings: [],
        status: 'proposing',
        selection: {},
      }

      setChronicleEntries((prev) => [...prev, baseEntry])
      setChronicleText('')

      const previous = [...entriesRef.current]
        .reverse()
        .find((entry) => entry.status === 'applied' || entry.status === 'ready')

      const context = previous
        ? {
            previousEntry: {
              id: previous.id,
              rawText: previous.rawText,
              timestamp: previous.createdAt.toISOString(),
            },
          }
        : undefined

      try {
        const { bundle, warnings } = await proposeEntryDeltas({
          entryId,
          rawText: trimmed,
          context,
        })

        const selection = buildSelectionMap(bundle.ops, warnings)
        const auto = shouldAutoApplyBundle(bundle, selection, warnings)
        const narrative =
          bundle.narrative?.trim() || enhanceNote(trimmed, campaignVibe)

        updateEntry(entryId, (entry) => ({
          ...entry,
          narrative,
          bundle,
          warnings,
          selection,
          status: auto ? 'applying' : 'ready',
          errorMessage: undefined,
        }))

        if (auto) {
          await applyBundleForEntry(entryId, { auto: true })
        }
      } catch (error) {
        const narrative = enhanceNote(trimmed, campaignVibe)
        const message =
          error instanceof Error ? error.message : 'Failed to parse note.'

        updateEntry(entryId, (entry) => ({
          ...entry,
          narrative,
          warnings: [],
          status: 'error',
          errorMessage: message,
        }))
      } finally {
        setTimeout(() => {
          if (chronicleTextareaRef.current) {
            chronicleTextareaRef.current.scrollTop =
              chronicleTextareaRef.current.scrollHeight
          }
        }, 100)
      }
    },
    [
      applyBundleForEntry,
      buildSelectionMap,
      campaignVibe,
      proposeEntryDeltas,
      shouldAutoApplyBundle,
    ],
  )

  const _handleDiceRoll = (roll: {
    finalResult: number
    modifier: number
    outcome: string
  }) => {
    const diceContext: DiceRollContext = {
      id: Math.random().toString(36).substr(2, 9),
      result: roll.finalResult,
      modifier: roll.modifier,
      stat: 'move',
      timestamp: new Date(),
      outcome: roll.outcome,
    }
    setPendingDiceContext(diceContext)
  }

  const _completeDiceContext = (context: string, outcome: string) => {
    if (pendingDiceContext) {
      const rollText = `${context} (${pendingDiceContext.stat} roll: ${pendingDiceContext.result}) - ${outcome}`
      void addChronicleEntry(rollText)
      setPendingDiceContext(null)
    }
  }

  const automationStatus = useMemo<AutomationSummary | null>(() => {
    const progressStage = lastProgressEvent?.stage
    const progressMessage =
      lastProgressEvent?.message ??
      (lastProgressEvent as { text?: string } | null)?.text ??
      ''

    if (progressStage === 'error') {
      return {
        label: 'Automation error',
        message:
          progressMessage || 'Chronicle could not apply the last update.',
        badgeVariant: 'destructive',
        alertVariant: 'destructive',
        icon: AlertTriangle,
        spinning: false,
      }
    }

    if (isApplyingBundle) {
      return {
        label: 'Applying updates',
        message: progressMessage || 'Syncing selected deltas to your sheet.',
        badgeVariant: 'outline',
        alertVariant: 'default',
        icon: Loader2,
        spinning: true,
      }
    }

    if (isProposing) {
      return {
        label: 'Drafting deltas',
        message: progressMessage || 'GPT-5 is parsing the latest note.',
        badgeVariant: 'outline',
        alertVariant: 'default',
        icon: Sparkles,
        spinning: false,
      }
    }

    if (lastTelemetryEvent) {
      const latency = `${Math.round(lastTelemetryEvent.latencyMs)} ms`
      const tokens = `${lastTelemetryEvent.usage.totalTokens} tokens`
      return {
        label: 'Automation ready',
        message: `${latency} ┬╖ ${tokens}`,
        badgeVariant: 'default',
        alertVariant: 'default',
        icon: CheckCircle2,
        spinning: false,
      }
    }

    return null
  }, [isApplyingBundle, isProposing, lastProgressEvent, lastTelemetryEvent])

  const automationBanner = useMemo(() => {
    if (!automationStatus) return null

    const Icon = automationStatus.icon

    return (
      <Alert variant={automationStatus.alertVariant} className='mb-4'>
        <Icon
          className={
            automationStatus.spinning ? 'h-4 w-4 animate-spin' : 'h-4 w-4'
          }
        />
        <AlertTitle className='text-sm font-semibold'>
          {automationStatus.label}
        </AlertTitle>
        {automationStatus.message && (
          <AlertDescription className='text-sm'>
            {automationStatus.message}
          </AlertDescription>
        )}
      </Alert>
    )
  }, [automationStatus])

  // Tool creation functions
  // Tool creation functions
  const handleCreateItem = () => {
    if (!itemInput.trim()) return
    const item = createItem(itemInput)
    setCreatedItems((prev) => [...prev, item])
    setItemInput('')
  }

  const handleCreateNPC = () => {
    if (!npcInput.trim()) return
    const npc = createNPC(npcInput)
    setCreatedNPCs((prev) => [...prev, npc])
    setNpcInput('')
  }

  const handleCreateMonster = () => {
    if (!monsterInput.trim()) return
    const monster = createMonster(monsterInput)
    setCreatedMonsters((prev) => [...prev, monster])
    setMonsterInput('')
  }

  if (!activeCharacter) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className={`p-4 ${className}`}
      >
        <Card variant='magical'>
          <CardContent className='p-6 pt-6'>
            <div className='text-center space-y-4'>
              <div className='w-12 h-12 mx-auto rounded-full bg-muted  flex items-center justify-center'>
                <BookOpen size={24} className='text-muted-foreground' />
              </div>
              <div>
                <h2 className='text-lg font-display mb-2'>
                  Ready to Chronicle?
                </h2>
                <p className='text-muted-foreground  text-sm mb-4'>
                  Create or select a character to begin your storytelling
                  adventure
                </p>
                <Button variant='primary' size='sm'>
                  Create Character
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </motion.div>
    )
  }

  const xpNeeded = getXPThreshold(activeCharacter.level)

  return (
    <div className={`flex h-screen overflow-hidden ${className}`}>
      {/* Collapsible Character Panel */}
      <motion.div
        initial={false}
        animate={{ width: characterPanelCollapsed ? 60 : 300 }}
        className='bg-muted/50  border-r border-border flex-shrink-0'
      >
        <div className='p-4'>
          <div className='flex items-center justify-between mb-4'>
            {!characterPanelCollapsed && (
              <h3 className='text-lg font-semibold'>{activeCharacter.name}</h3>
            )}
            <Button
              variant='ghost'
              size='sm'
              onClick={() =>
                setCharacterPanelCollapsed(!characterPanelCollapsed)
              }
              className='p-2'
            >
              {characterPanelCollapsed ? (
                <ChevronRight size={16} />
              ) : (
                <ChevronLeft size={16} />
              )}
            </Button>
          </div>

          {!characterPanelCollapsed && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className='space-y-4'
            >
              <div className='text-sm text-muted-foreground'>
                Level {activeCharacter.level} {activeCharacter.class}
              </div>

              {/* Campaign Vibe Selector */}
              <div className='space-y-2'>
                <label
                  htmlFor='campaign-setting'
                  className='text-xs font-medium text-foreground '
                >
                  Campaign Setting
                </label>
                <select
                  id='campaign-setting'
                  value={campaignVibe}
                  onChange={(e) =>
                    setCampaignVibe(e.target.value as CampaignVibe)
                  }
                  className='w-full text-xs p-2 rounded border border-border bg-card'
                >
                  {Object.entries(campaignVibes).map(([key, config]) => (
                    <option key={key} value={key}>
                      {config.name}
                    </option>
                  ))}
                </select>
                <div className='text-xs text-muted-foreground'>
                  Current: {campaignVibes[campaignVibe].name}
                </div>
              </div>

              <div className='space-y-3'>
                <div>
                  <div className='flex justify-between text-xs mb-1'>
                    <span>Health</span>
                    <span>
                      {activeCharacter.hp.current}/{activeCharacter.hp.max}
                    </span>
                  </div>
                  <Progress
                    value={activeCharacter.hp.current}
                    max={activeCharacter.hp.max}
                    variant='health'
                    className='h-2'
                  />
                </div>

                <div>
                  <div className='flex justify-between text-xs mb-1'>
                    <span>XP</span>
                    <span>
                      {activeCharacter.xp}/{xpNeeded}
                    </span>
                  </div>
                  <Progress
                    value={activeCharacter.xp}
                    max={xpNeeded}
                    variant='experience'
                    className='h-2'
                  />
                </div>
              </div>

              <div className='pt-2 border-t border-border'>
                <div className='flex items-center gap-2 mb-2'>
                  <div
                    className={`w-2 h-2 rounded-full ${isSessionActive ? 'bg-chart-2' : 'bg-gray-400'}`}
                  />
                  <span className='text-xs font-medium'>
                    {isSessionActive ? `${sessionTime}m` : 'Paused'}
                  </span>
                </div>
                <Button
                  variant={isSessionActive ? 'destructive' : 'primary'}
                  size='sm'
                  onClick={isSessionActive ? endSession : startSession}
                  className='w-full text-xs'
                >
                  {isSessionActive ? 'End Session' : 'Start Session'}
                </Button>
              </div>
            </motion.div>
          )}
        </div>
      </motion.div>

      {/* Main Content Area */}
      <div className='flex-1 flex flex-col overflow-hidden'>
        {/* Tab Navigation */}
        <div className='border-b border-border bg-card'>
          <div className='flex'>
            <Button
              variant={activeTab === 'chronicle' ? 'primary' : 'ghost'}
              onClick={() => setActiveTab('chronicle')}
              className='rounded-none border-b-2 border-transparent data-[active]:border-primary'
              data-active={activeTab === 'chronicle'}
            >
              <BookOpen size={16} />
              Chronicle
            </Button>
            <Button
              variant={activeTab === 'tools' ? 'primary' : 'ghost'}
              onClick={() => setActiveTab('tools')}
              className='rounded-none border-b-2 border-transparent data-[active]:border-primary'
              data-active={activeTab === 'tools'}
            >
              <Wrench size={16} />
              Tools
            </Button>
          </div>
        </div>

        {/* Tab Content */}
        <div className='flex-1 overflow-hidden'>
          <div className='px-6 pt-6 pb-0'>{automationBanner}</div>
          <AnimatePresence mode='wait'>
            {activeTab === 'chronicle' && (
              <motion.div
                key='chronicle'
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                className='h-full flex flex-col p-6'
              >
                {/* Chronicle Canvas - 60% of available space */}
                <div className='flex-1 mb-6'>
                  <Card variant='parchment' className='h-full'>
                    <CardContent className='p-6 h-full flex flex-col'>
                      <div className='flex items-center justify-between mb-4'>
                        <h2 className='text-xl font-display flex items-center gap-2'>
                          <Scroll size={20} className='text-primary' />
                          Your Story
                          {automationStatus && (
                            <Badge
                              variant={automationStatus.badgeVariant}
                              className='text-xs flex items-center gap-1'
                            >
                              <automationStatus.icon
                                className={
                                  automationStatus.spinning
                                    ? 'h-3.5 w-3.5 animate-spin'
                                    : 'h-3.5 w-3.5'
                                }
                              />
                              {automationStatus.label}
                            </Badge>
                          )}
                        </h2>
                        <Badge variant='secondary' className='text-xs'>
                          {chronicleEntries.length} entries
                        </Badge>
                      </div>

                      {/* Chronicle Text Area */}
                      <div className='flex-1 flex flex-col'>
                        <Textarea
                          ref={chronicleTextareaRef}
                          value={chronicleText}
                          onChange={(e) => setChronicleText(e.target.value)}
                          placeholder="What happens in your adventure? Write your story here...

Tip: Write naturally - 'fought goblins, got hurt' becomes 'You battled the goblin raiders, suffering wounds in the fierce struggle.'"
                          className='flex-1 resize-none text-base leading-relaxed font-serif'
                          style={{ minHeight: '400px' }}
                        />

                        <div className='flex justify-between items-center mt-4'>
                          <div className='flex items-center gap-2'>
                            <Sparkles size={14} className='text-primary' />
                            <span className='text-xs text-muted-foreground'>
                              GPT-5 automation parses every note
                            </span>
                          </div>
                          <Button
                            onClick={() =>
                              void addChronicleEntry(chronicleText)
                            }
                            disabled={!chronicleText.trim() || isProposing}
                            className='gap-2'
                          >
                            {isProposing ? (
                              <>
                                <Loader2 className='h-4 w-4 animate-spin' />
                                Parsing...
                              </>
                            ) : (
                              <>
                                <Send size={16} />
                                Add to Chronicle
                              </>
                            )}
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>

                {/* Recent Entries & Dice Context */}
                <div className='grid grid-cols-1 gap-6 lg:grid-cols-2'>
                  <div className='space-y-6'>
                    {/* Recent Chronicle Entries */}
                    <Card variant='surface'>
                      <CardContent className='p-4'>
                        <h3 className='font-semibold mb-3 flex items-center gap-2'>
                          <BookOpen size={16} />
                          Recent Story
                        </h3>
                        <div className='space-y-3 max-h-72 overflow-y-auto'>
                          {[...chronicleEntries]
                            .slice(-5)
                            .reverse()
                            .map((entry) => {
                              const statusLabel = (() => {
                                switch (entry.status) {
                                  case 'proposing':
                                    return 'Drafting'
                                  case 'applying':
                                    return 'Applying'
                                  case 'applied':
                                    return 'Applied'
                                  case 'error':
                                    return 'Needs review'
                                  default:
                                    return 'Ready'
                                }
                              })()

                              const badgeVariant = (
                                entry.status === 'applied'
                                  ? 'default'
                                  : entry.status === 'error'
                                    ? 'destructive'
                                    : 'outline'
                              ) as 'default' | 'destructive' | 'outline'

                              return (
                                <div
                                  key={`${entry.id}`}
                                  className='rounded-lg border border-border/60 bg-card p-3 shadow-sm'
                                >
                                  <div className='flex flex-wrap items-center justify-between gap-2'>
                                    <div className='flex items-center gap-2'>
                                      <Badge
                                        variant={badgeVariant}
                                        className='text-[10px] uppercase tracking-wide'
                                      >
                                        {statusLabel}
                                      </Badge>
                                      <span className='text-xs text-muted-foreground'>
                                        {entry.createdAt.toLocaleTimeString()}
                                      </span>
                                    </div>
                                    {entry.bundle &&
                                      entry.bundle.ops.length > 0 && (
                                        <span className='text-[11px] text-muted-foreground'>
                                          {entry.bundle.ops.length} update
                                          {entry.bundle.ops.length === 1
                                            ? ''
                                            : 's'}
                                        </span>
                                      )}
                                  </div>

                                  <div className='mt-2 text-sm leading-relaxed whitespace-pre-wrap'>
                                    {entry.narrative ?? entry.rawText}
                                  </div>

                                  {entry.narrative &&
                                    entry.narrative !== entry.rawText && (
                                      <div className='mt-2 text-[11px] text-muted-foreground italic'>
                                        {entry.rawText}
                                      </div>
                                    )}

                                  {entry.warnings.length > 0 && (
                                    <Alert
                                      variant='destructive'
                                      className='mt-3'
                                    >
                                      <AlertTitle className='text-xs font-semibold flex items-center gap-1'>
                                        <AlertTriangle className='h-3.5 w-3.5' />
                                        Review this note
                                      </AlertTitle>
                                      <AlertDescription className='text-xs space-y-1'>
                                        {entry.warnings.map(
                                          (warning, warningIndex) => (
                                            <div key={warningIndex}>
                                              {warning}
                                            </div>
                                          ),
                                        )}
                                      </AlertDescription>
                                    </Alert>
                                  )}

                                  {entry.bundle &&
                                    entry.bundle.ops.length > 0 && (
                                      <div className='mt-3 space-y-2'>
                                        <span className='text-[11px] uppercase tracking-wide text-muted-foreground'>
                                          Proposed updates
                                        </span>
                                        <DeltaChecklist
                                          operations={entry.bundle.ops}
                                          selection={entry.selection}
                                          onToggle={(index, checked) =>
                                            toggleOperationSelection(
                                              entry.id,
                                              index,
                                              checked,
                                            )
                                          }
                                          disabled={
                                            entry.status === 'applied' ||
                                            entry.status === 'applying'
                                          }
                                          renderDescription={
                                            describeDeltaOperation
                                          }
                                          showRuleReference
                                        />
                                        <div className='flex flex-wrap items-center gap-2 pt-1'>
                                          <Button
                                            size='sm'
                                            variant={
                                              entry.status === 'applied'
                                                ? 'outline'
                                                : 'primary'
                                            }
                                            onClick={() =>
                                              void applyBundleForEntry(entry.id)
                                            }
                                            disabled={
                                              entry.status === 'applying' ||
                                              isApplyingBundle
                                            }
                                            className='gap-2'
                                          >
                                            {entry.status === 'applying' ? (
                                              <>
                                                <Loader2 className='h-4 w-4 animate-spin' />
                                                Applying...
                                              </>
                                            ) : entry.status === 'applied' ? (
                                              <>
                                                <CheckCircle2 className='h-4 w-4 text-emerald-500' />
                                                Applied
                                              </>
                                            ) : (
                                              <>
                                                <CheckCircle2 className='h-4 w-4' />
                                                Apply selected
                                              </>
                                            )}
                                          </Button>
                                          {entry.result && (
                                            <span className='text-[11px] text-muted-foreground'>
                                              {entry.result.appliedOps.length}{' '}
                                              applied
                                              {entry.result.skippedOps.length >
                                              0
                                                ? ` ┬╖ ${entry.result.skippedOps.length} skipped`
                                                : ''}
                                            </span>
                                          )}
                                        </div>
                                      </div>
                                    )}

                                  {entry.errorMessage && (
                                    <Alert
                                      variant='destructive'
                                      className='mt-3'
                                    >
                                      <AlertTitle className='text-xs font-semibold'>
                                        Automation failed
                                      </AlertTitle>
                                      <AlertDescription className='text-xs'>
                                        {entry.errorMessage}
                                      </AlertDescription>
                                    </Alert>
                                  )}
                                </div>
                              )
                            })}
                          {chronicleEntries.length === 0 && (
                            <div className='text-center text-muted-foreground py-8'>
                              <BookOpen
                                size={32}
                                className='mx-auto mb-2 opacity-50'
                              />
                              <p className='text-sm'>
                                Your chronicle awaits...
                              </p>
                            </div>
                          )}
                        </div>
                      </CardContent>
                    </Card>

                    {/* Automation Log */}
                    <Card variant='surface'>
                      <CardContent className='p-4'>
                        <div className='flex items-center justify-between mb-3'>
                          <h3 className='font-semibold flex items-center gap-2'>
                            <Sparkles size={16} />
                            Automation Log
                          </h3>
                          <span className='text-xs text-muted-foreground'>
                            Last
                            {Math.min(recentDeltaHistory.length, 5)} bundles
                          </span>
                        </div>
                        {recentDeltaHistory.length === 0 ? (
                          <div className='text-sm text-muted-foreground'>
                            Run a Dungeon World move or jot a note to see
                            Chronicle's updates.
                          </div>
                        ) : (
                          <div className='space-y-3 max-h-72 overflow-y-auto'>
                            {recentDeltaHistory.map((log) => {
                              const createdAt = new Date(log.createdAt)
                              const appliedCount = log.appliedOps.length
                              const skippedCount = log.skippedOps.length
                              return (
                                <div
                                  key={log.bundleId}
                                  className='rounded-md border border-border/60 bg-card p-3'
                                >
                                  <div className='flex flex-wrap items-center justify-between gap-2'>
                                    <div className='space-y-0.5'>
                                      <div className='text-xs text-muted-foreground'>
                                        {createdAt.toLocaleTimeString()}
                                      </div>
                                      <div className='text-sm font-medium leading-tight'>
                                        Entry
                                        {log.entryId}
                                      </div>
                                    </div>
                                    <Badge
                                      variant='outline'
                                      className='text-[10px] uppercase tracking-wide'
                                    >
                                      {appliedCount} applied
                                      {skippedCount > 0
                                        ? ` / ${skippedCount} skipped`
                                        : ''}
                                    </Badge>
                                  </div>
                                  {log.appliedOps.length > 0 && (
                                    <div className='mt-2'>
                                      <DeltaChecklist
                                        operations={log.appliedOps}
                                        renderDescription={
                                          describeDeltaOperation
                                        }
                                        variant='readOnly'
                                        size='compact'
                                        showRuleReference
                                        className='space-y-1'
                                        itemClassName='bg-transparent border-border/40'
                                      />
                                    </div>
                                  )}
                                  {skippedCount > 0 && (
                                    <Alert variant='outline' className='mt-3'>
                                      <AlertTitle className='text-xs font-semibold'>
                                        Skipped
                                      </AlertTitle>
                                      <AlertDescription className='text-xs space-y-0.5'>
                                        <DeltaChecklist
                                          operations={log.skippedOps}
                                          renderDescription={
                                            describeDeltaOperation
                                          }
                                          variant='readOnly'
                                          size='compact'
                                          showRuleReference
                                          className='space-y-1'
                                          itemClassName='bg-transparent border-none p-0'
                                        />
                                      </AlertDescription>
                                    </Alert>
                                  )}
                                  <div className='mt-3 flex flex-wrap items-center gap-2'>
                                    <Button
                                      size='xs'
                                      variant='outline'
                                      disabled={
                                        !log.undoHandle ||
                                        undoingBundleId === log.bundleId
                                      }
                                      onClick={() =>
                                        void handleUndoBundle(log.bundleId)
                                      }
                                      className='gap-2'
                                    >
                                      {undoingBundleId === log.bundleId ? (
                                        <>
                                          <Loader2 className='h-3.5 w-3.5 animate-spin' />
                                          Undoing
                                        </>
                                      ) : (
                                        <>
                                          <RefreshCcw className='h-3.5 w-3.5' />
                                          Undo
                                        </>
                                      )}
                                    </Button>
                                    <Button
                                      size='xs'
                                      variant='ghost'
                                      disabled={
                                        undoingBundleId === log.bundleId
                                      }
                                      onClick={() =>
                                        clearDeltaLog(log.bundleId)
                                      }
                                    >
                                      Dismiss
                                    </Button>
                                  </div>
                                </div>
                              )
                            })}
                          </div>
                        )}
                      </CardContent>
                    </Card>
                  </div>

                  <div className='space-y-6'>
                    {/* Tools Sub-navigation */}
                    <div className='flex gap-2 mb-6'>
                      <Button
                        variant={
                          toolsSubTab === 'items' ? 'primary' : 'outline'
                        }
                        onClick={() => setToolsSubTab('items')}
                        size='sm'
                      >
                        <Sword size={16} />
                        Items
                      </Button>
                      <Button
                        variant={
                          toolsSubTab === 'monsters' ? 'primary' : 'outline'
                        }
                        onClick={() => setToolsSubTab('monsters')}
                        size='sm'
                      >
                        <Crown size={16} />
                        Monsters
                      </Button>
                      <Button
                        variant={toolsSubTab === 'npcs' ? 'primary' : 'outline'}
                        onClick={() => setToolsSubTab('npcs')}
                        size='sm'
                      >
                        <User size={16} />
                        NPCs
                      </Button>
                    </div>

                    {/* Tools Content */}
                    <div className='grid grid-cols-2 gap-6'>
                      {/* Creator Panel */}
                      <Card variant='elevated'>
                        <CardContent className='p-4'>
                          <h3 className='font-semibold mb-3'>
                            Create{' '}
                            {toolsSubTab === 'items'
                              ? 'Item'
                              : toolsSubTab === 'monsters'
                                ? 'Monster'
                                : 'NPC'}
                          </h3>
                          <div className='space-y-3'>
                            <Input
                              value={
                                toolsSubTab === 'items'
                                  ? itemInput
                                  : toolsSubTab === 'monsters'
                                    ? monsterInput
                                    : npcInput
                              }
                              onChange={(e) => {
                                if (toolsSubTab === 'items')
                                  setItemInput(e.target.value)
                                else if (toolsSubTab === 'monsters')
                                  setMonsterInput(e.target.value)
                                else setNpcInput(e.target.value)
                              }}
                              placeholder={`Describe your ${toolsSubTab.slice(0, -1)}...`}
                            />
                            <Button
                              onClick={
                                toolsSubTab === 'items'
                                  ? handleCreateItem
                                  : toolsSubTab === 'monsters'
                                    ? handleCreateMonster
                                    : handleCreateNPC
                              }
                              className='w-full gap-2'
                            >
                              <Sparkles size={16} />
                              Create with AI
                            </Button>
                          </div>
                        </CardContent>
                      </Card>

                      {/* Created Items List */}
                      <Card variant='surface'>
                        <CardContent className='p-4'>
                          <h3 className='font-semibold mb-3'>
                            Your{' '}
                            {toolsSubTab.charAt(0).toUpperCase() +
                              toolsSubTab.slice(1)}
                          </h3>
                          <div className='space-y-3 max-h-96 overflow-y-auto'>
                            {toolsSubTab === 'items' &&
                              createdItems.map((item) => (
                                <div
                                  key={item.id}
                                  className='p-3 bg-card rounded border'
                                >
                                  <div className='font-medium'>{item.name}</div>
                                  <div className='text-xs text-muted-foreground'>
                                    {item.tags.join(', ')}
                                  </div>
                                  <div className='text-sm mt-1'>
                                    {item.description}
                                  </div>
                                  <div className='text-xs font-mono mt-1'>
                                    {item.stats}
                                  </div>
                                </div>
                              ))}

                            {toolsSubTab === 'monsters' &&
                              createdMonsters.map((monster) => (
                                <div
                                  key={monster.id}
                                  className='p-3 bg-card rounded border'
                                >
                                  <div className='font-medium'>
                                    {monster.name}
                                  </div>
                                  <div className='text-xs text-muted-foreground'>
                                    {monster.hp} HP, {monster.armor} armor
                                  </div>
                                  <div className='text-sm mt-1'>
                                    {monster.instinct}
                                  </div>
                                  <ul className='text-xs mt-1 list-disc list-inside'>
                                    {monster.moves.map((move, i) => (
                                      <li key={i}>{move}</li>
                                    ))}
                                  </ul>
                                </div>
                              ))}

                            {toolsSubTab === 'npcs' &&
                              createdNPCs.map((npc) => (
                                <div
                                  key={npc.id}
                                  className='p-3 bg-card rounded border'
                                >
                                  <div className='font-medium'>{npc.name}</div>
                                  <div className='text-xs text-muted-foreground'>
                                    {npc.quirk}
                                  </div>
                                  <div className='text-sm mt-1'>
                                    {npc.appearance}
                                  </div>
                                  <div className='text-xs mt-1'>
                                    <strong>Drive:</strong> {npc.drive}
                                  </div>
                                  <div className='text-xs'>
                                    <strong>Knows:</strong> {npc.knows}
                                  </div>
                                </div>
                              ))}
                          </div>
                        </CardContent>
                      </Card>
                    </div>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  )
}

export default PlayTab

/**
 * CharacterStatusWidget - At-a-Glance Character Vitals
 *
 * Always-visible character status including animated health orb,
 * load meter, XP progress, active bonds, and debilities.
 */

import type { Character } from '../../../models/Character'
import type { GameMode, PlayTabTheme } from '../PlayTab'
import { AnimatePresence, motion } from 'framer-motion'
import { Droplets, Heart, Package, Shield, Star, Wind } from 'lucide-react'
import React, { useEffect, useState } from 'react'
import { logger } from '@/utils/logger'
import { Badge, Button, Card, CardContent } from '../../ui'

interface CharacterStatusWidgetProps {
  character: Character
  gameMode: GameMode
  theme: PlayTabTheme
  className?: string
}

interface HealthOrbProps {
  current: number
  max: number
  size?: number
  variant?: 'primary' | 'danger' | 'warning'
}

const HealthOrb: React.FC<HealthOrbProps> = ({
  current,
  max,
  size = 80,
  variant: _variant = 'primary',
}) => {
  const percentage = Math.max(0, Math.min(100, (current / max) * 100))
  const strokeDasharray = 2 * Math.PI * (size / 2 - 8)
  const strokeDashoffset =
    strokeDasharray - (strokeDasharray * percentage) / 100

  const getColor = () => {
    if (percentage <= 25) return 'text-destructive'
    if (percentage <= 50) return 'text-chart-4'
    return 'text-chart-2'
  }

  const getPulseIntensity = () => {
    if (percentage <= 25) return 'animate-pulse'
    return ''
  }

  return (
    <div className='relative flex items-center justify-center'>
      <svg
        width={size}
        height={size}
        className={`transform -rotate-90 ${getPulseIntensity()}`}
      >
        {/* Background circle */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={size / 2 - 8}
          stroke='currentColor'
          strokeWidth='4'
          fill='none'
          className='text-muted-foreground'
        />
        {/* Progress circle */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={size / 2 - 8}
          stroke='currentColor'
          strokeWidth='6'
          fill='none'
          className={getColor()}
          strokeDasharray={strokeDasharray}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap='round'
          initial={{ strokeDashoffset: strokeDasharray }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1, ease: 'easeOut' }}
        />
      </svg>

      {/* Center content */}
      <div className='absolute inset-0 flex flex-col items-center justify-center'>
        <Heart size={16} className={`${getColor()} mb-1`} />
        <span className='text-lg font-bold font-display'>{current}</span>
        <span className='text-xs text-muted-foreground'>/{max}</span>
      </div>
    </div>
  )
}

const LoadMeter: React.FC<{ current: number; max: number }> = ({
  current,
  max,
}) => {
  const percentage = Math.max(0, Math.min(100, (current / max) * 100))
  const isNearCapacity = percentage >= 80
  const isOverloaded = current > max

  return (
    <div className='space-y-2'>
      <div className='flex items-center justify-between text-sm'>
        <span className='flex items-center gap-1'>
          <Package size={14} />
          Load
        </span>
        <span className={`font-mono ${isOverloaded ? 'text-destructive' : ''}`}>
          {current}/{max}
        </span>
      </div>

      <div className='relative h-2 bg-muted  rounded-full overflow-hidden'>
        <motion.div
          className={`h-full rounded-full ${
            isOverloaded
              ? 'bg-destructive/120'
              : isNearCapacity
                ? 'bg-chart-4/120'
                : 'bg-chart-2'
          }`}
          initial={{ width: 0 }}
          animate={{ width: `${Math.min(100, percentage)}%` }}
          transition={{ duration: 0.8, ease: 'easeOut' }}
        />

        {isOverloaded && (
          <motion.div
            className='absolute top-0 right-0 h-full bg-destructive'
            style={{ width: `${((current - max) / max) * 100}%` }}
            animate={{ opacity: [0.6, 1, 0.6] }}
            transition={{ duration: 1, repeat: Infinity }}
          />
        )}
      </div>
    </div>
  )
}

const XPTracker: React.FC<{ xp: number; level: number }> = ({ xp, level }) => {
  const xpToNext = (level + 1) * 7 - xp
  const progress = xp - level * 7
  const progressMax = 7

  return (
    <div className='space-y-2'>
      <div className='flex items-center justify-between text-sm'>
        <span className='flex items-center gap-1'>
          <Star size={14} />
          Level {level}
        </span>
        <span className='text-xs text-muted-foreground'>
          {xpToNext} XP to next
        </span>
      </div>

      <div className='relative h-1.5 bg-muted  rounded-full overflow-hidden'>
        <motion.div
          className='h-full bg-gradient-to-r from-accent to-primary rounded-full'
          initial={{ width: 0 }}
          animate={{ width: `${(progress / progressMax) * 100}%` }}
          transition={{ duration: 0.6, ease: 'easeOut' }}
        />
      </div>
    </div>
  )
}

const StatusEffect: React.FC<{
  type: 'debility' | 'condition' | 'buff'
  name: string
  icon: React.ReactNode
  color: string
}> = ({ type: _type, name, icon, color }) => {
  return (
    <motion.div
      initial={{ scale: 0 }}
      animate={{ scale: 1 }}
      className={`p-1.5 rounded-full ${color} text-white text-xs flex items-center justify-center`}
      title={name}
      whileHover={{ scale: 1.1 }}
    >
      {icon}
    </motion.div>
  )
}

export const CharacterStatusWidget: React.FC<CharacterStatusWidgetProps> = ({
  character,
  gameMode,
  theme,
  className = '',
}) => {
  const [isExpanded, setIsExpanded] = useState(false)
  const [recentDamage, setRecentDamage] = useState<number | null>(null)

  // Calculate derived stats
  const armorTotal = character.armor || 0
  const loadCurrent = character.load?.current || 0
  const loadMax = character.load?.max || 10
  const xp = character.xp || 0
  const level = character.level || 1

  // Animate damage feedback
  useEffect(() => {
    if (recentDamage !== null) {
      const timer = setTimeout(() => setRecentDamage(null), 2000)
      return () => clearTimeout(timer)
    }
  }, [recentDamage])

  // Mock status effects (replace with real character state)
  const statusEffects = [
    // Example debilities
    ...(character.debilities?.weak
      ? [
          {
            type: 'debility',
            name: 'Weak',
            icon: <Droplets size={12} />,
            color: 'bg-destructive/120',
          },
        ]
      : []),
    ...(character.debilities?.shaky
      ? [
          {
            type: 'debility',
            name: 'Shaky',
            icon: <Wind size={12} />,
            color: 'bg-chart-4/120',
          },
        ]
      : []),
    // Add more status effects as needed
  ]

  const cardVariant =
    theme === 'combat'
      ? 'elevated'
      : theme === 'dungeon'
        ? 'parchment'
        : theme === 'tavern'
          ? 'magical'
          : 'glass'

  return (
    <Card
      variant={cardVariant}
      className={`h-full relative overflow-hidden ${className}`}
    >
      <CardContent className='h-full flex flex-col'>
        {/* Character Name & Portrait */}
        <div className='text-center mb-4'>
          <motion.div
            className='w-12 h-12 mx-auto mb-2 rounded-full bg-gradient-to-br from-primary to-accent flex items-center justify-center text-white font-bold text-lg'
            whileHover={{ scale: 1.05 }}
            onClick={() => setIsExpanded(!isExpanded)}
          >
            {character.name.charAt(0).toUpperCase()}
          </motion.div>
          <h3 className='font-display text-sm font-medium truncate'>
            {character.name}
          </h3>
          <p className='text-xs text-muted-foreground capitalize'>
            {character.class} ΓÇó Level
            {level}
          </p>
        </div>

        {/* Health Orb */}
        <div className='flex justify-center mb-4'>
          <HealthOrb
            current={character.hitPoints?.current || 0}
            max={character.hitPoints?.max || 1}
            size={64}
          />
        </div>

        {/* Damage Feedback */}
        <AnimatePresence>
          {recentDamage && (
            <motion.div
              initial={{ opacity: 0, y: -20, scale: 0.8 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -40, scale: 0.6 }}
              className='absolute top-4 right-4 bg-destructive/120 text-white px-2 py-1 rounded text-xs font-bold'
            >
              -{recentDamage}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Core Stats */}
        <div className='space-y-3 flex-1'>
          {/* Armor */}
          <div className='flex items-center justify-between text-sm'>
            <span className='flex items-center gap-1'>
              <Shield size={14} />
              Armor
            </span>
            <span className='font-mono'>{armorTotal}</span>
          </div>

          {/* Load */}
          <LoadMeter current={loadCurrent} max={loadMax} />

          {/* XP Progress */}
          <XPTracker xp={xp} level={level} />
        </div>

        {/* Status Effects */}
        {statusEffects.length > 0 && (
          <div className='mt-4'>
            <div className='text-xs text-muted-foreground mb-2'>
              Status Effects
            </div>
            <div className='flex flex-wrap gap-1'>
              {statusEffects.map((effect, index) => (
                <StatusEffect
                  key={index}
                  type={effect.type as any}
                  name={effect.name}
                  icon={effect.icon}
                  color={effect.color}
                />
              ))}
            </div>
          </div>
        )}

        {/* Game Mode Indicator */}
        <div className='mt-4 pt-3 border-t border-border'>
          <Badge
            variant='secondary'
            className={`w-full justify-center text-xs ${
              gameMode === 'combat'
                ? 'bg-destructive/15 text-destructive'
                : gameMode === 'exploration'
                  ? 'bg-chart-2/15 text-chart-2'
                  : gameMode === 'social'
                    ? 'bg-primary/10 text-primary'
                    : 'bg-accent/15 text-accent'
            }`}
          >
            {gameMode.toUpperCase()}
          </Badge>
        </div>

        {/* Quick Actions */}
        <div className='mt-3 flex gap-1'>
          <Button
            variant='ghost'
            size='sm'
            className='flex-1 text-xs'
            onClick={() => {
              // Quick heal action
              logger.info('character_quick_heal', { characterId: character.id })
            }}
          >
            <Heart size={12} className='mr-1' />
            Heal
          </Button>
          <Button
            variant='ghost'
            size='sm'
            className='flex-1 text-xs'
            onClick={() => {
              // Mark XP action
              logger.info('character_quick_xp', { characterId: character.id })
            }}
          >
            <Star size={12} className='mr-1' />
            XP
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

export default CharacterStatusWidget

/**
 * SessionFlowControls - Session Management Tools
 *
 * Handles session timing, break reminders, and session flow controls.
 */

import { motion } from 'framer-motion'
import { Clock, Coffee, Pause, Play, Square } from 'lucide-react'
import React, { useEffect, useState } from 'react'
import { Badge, Button } from '../../ui'

interface SessionFlowControlsProps {
  sessionStartTime: Date | null
  onEndSession: () => void
  className?: string
}

export const SessionFlowControls: React.FC<SessionFlowControlsProps> = ({
  sessionStartTime,
  onEndSession,
  className = '',
}) => {
  const [sessionDuration, setSessionDuration] = useState(0)
  const [isPaused, setIsPaused] = useState(false)
  const [pausedTime, _setPausedTime] = useState(0)

  // Update session duration every minute
  useEffect(() => {
    if (!sessionStartTime || isPaused) return

    const interval = setInterval(() => {
      const now = new Date()
      const duration =
        Math.floor((now.getTime() - sessionStartTime.getTime()) / 60000) -
        pausedTime
      setSessionDuration(Math.max(0, duration))
    }, 60000) // Update every minute

    // Initial calculation
    const now = new Date()
    const duration =
      Math.floor((now.getTime() - sessionStartTime.getTime()) / 60000) -
      pausedTime
    setSessionDuration(Math.max(0, duration))

    return () => clearInterval(interval)
  }, [sessionStartTime, isPaused, pausedTime])

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60)
    const mins = minutes % 60

    if (hours > 0) {
      return `${hours}h ${mins}m`
    }
    return `${mins}m`
  }

  const getSessionStatus = () => {
    if (sessionDuration >= 180)
      return { status: 'Long session', color: 'text-destructive' }
    if (sessionDuration >= 120)
      return { status: 'Extended play', color: 'text-chart-4' }
    if (sessionDuration >= 60)
      return { status: 'Good session', color: 'text-chart-2' }
    return { status: 'Getting started', color: 'text-primary' }
  }

  const handlePauseToggle = () => {
    if (isPaused) {
      // Resuming - don't add to paused time yet
      setIsPaused(false)
    } else {
      // Pausing - start tracking pause time
      setIsPaused(true)
      // In a real implementation, we'd track the pause start time
    }
  }

  const suggestBreak =
    sessionDuration > 0 && sessionDuration % 90 === 0 && !isPaused

  const sessionInfo = getSessionStatus()

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      {/* Session Duration */}
      <div className='flex items-center gap-2'>
        <Clock size={16} className='text-muted-foreground' />
        <span className='font-mono text-sm'>
          {formatDuration(sessionDuration)}
        </span>
        <Badge variant='secondary' className={`text-xs ${sessionInfo.color}`}>
          {sessionInfo.status}
        </Badge>
      </div>

      {/* Session Controls */}
      <div className='flex items-center gap-1'>
        <Button
          variant='ghost'
          size='sm'
          onClick={handlePauseToggle}
          className='gap-1'
        >
          {isPaused ? <Play size={14} /> : <Pause size={14} />}
          {isPaused ? 'Resume' : 'Pause'}
        </Button>

        <Button
          variant='outline'
          size='sm'
          onClick={onEndSession}
          className='gap-1 text-destructive hover:text-destructive'
        >
          <Square size={14} />
          End Session
        </Button>
      </div>

      {/* Break Suggestion */}
      {suggestBreak && (
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className='flex items-center gap-1 text-xs text-chart-4'
        >
          <Coffee size={12} />
          <span>Consider a break</span>
        </motion.div>
      )}
    </div>
  )
}

export default SessionFlowControls

/**
 * SmartContextPanel - AI Game Assistant
 *
 * Provides contextual suggestions, situation awareness, and smart
 * recommendations based on current game state and recent actions.
 */

import type { Character } from '../../../models/Character'
import type { GameMode, PlayTabTheme } from '../PlayTab'
import { AnimatePresence, motion } from 'framer-motion'
import {
  AlertTriangle,
  ArrowRight,
  BookOpen,
  Brain,
  Eye,
  Heart,
  Lightbulb,
  Shield,
  Target,
  Users,
} from 'lucide-react'
import React, { useEffect, useMemo, useState } from 'react'
import { logger } from '@/utils/logger'
import {
  Badge,
  Button,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from '../../ui'

interface SmartContextPanelProps {
  character: Character
  gameMode: GameMode
  theme: PlayTabTheme
  chronicleEnabled: boolean
  className?: string
}

interface Suggestion {
  id: string
  type: 'tip' | 'warning' | 'opportunity' | 'chronicle'
  title: string
  description: string
  icon: React.ComponentType<{ size?: number; className?: string }>
  priority: 'high' | 'medium' | 'low'
  action?: {
    label: string
    onClick: () => void
  }
}

const SuggestionCard: React.FC<{
  suggestion: Suggestion
  onDismiss: (id: string) => void
}> = ({ suggestion, onDismiss }) => {
  const Icon = suggestion.icon

  const priorityColor = {
    high: 'border-destructive/30 bg-destructive/12',
    medium: 'border-chart-4/30 bg-chart-4/12 bg-chart-4/20',
    low: 'border-primary/30 bg-primary/10',
  }

  const iconColor = {
    tip: 'text-primary',
    warning: 'text-destructive',
    opportunity: 'text-chart-2',
    chronicle: 'text-accent',
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className={`p-3 rounded-lg border ${priorityColor[suggestion.priority]} relative`}
    >
      <button
        type='button'
        onClick={() => onDismiss(suggestion.id)}
        className='absolute top-2 right-2 w-4 h-4 text-muted-foreground hover:text-muted-foreground text-xs'
      >
        ├ù
      </button>

      <div className='flex items-start gap-3 pr-6'>
        <Icon size={16} className={iconColor[suggestion.type]} />
        <div className='flex-1 min-w-0'>
          <h4 className='text-sm font-medium mb-1'>{suggestion.title}</h4>
          <p className='text-xs text-muted-foreground  mb-2'>
            {suggestion.description}
          </p>
          {suggestion.action && (
            <Button
              size='sm'
              variant='ghost'
              onClick={suggestion.action.onClick}
              className='text-xs px-2 py-1 h-auto'
            >
              {suggestion.action.label}
              <ArrowRight size={10} className='ml-1' />
            </Button>
          )}
        </div>
      </div>
    </motion.div>
  )
}

const SituationBar: React.FC<{
  situation: string
  confidence: number
  gameMode: GameMode
}> = ({ situation, confidence, gameMode }) => {
  const modeColor = {
    combat: 'bg-destructive/120',
    exploration: 'bg-chart-2',
    social: 'bg-primary/100',
    rest: 'bg-accent',
  }

  return (
    <div className='space-y-2'>
      <div className='flex items-center justify-between text-sm'>
        <span className='font-medium'>Current Situation</span>
        <Badge variant='secondary' className='text-xs'>
          {confidence}% confident
        </Badge>
      </div>
      <div className={`p-3 rounded-lg ${modeColor[gameMode]} text-white`}>
        <p className='text-sm'>{situation}</p>
      </div>
    </div>
  )
}

const QuickStats: React.FC<{ character: Character }> = ({ character }) => {
  const hp = character.hitPoints?.current || 0
  const maxHP = character.hitPoints?.max || 1
  const armor = character.armor || 0
  const load = character.load?.current || 0
  const maxLoad = character.load?.max || 10

  const hpPercentage = (hp / maxHP) * 100
  const loadPercentage = (load / maxLoad) * 100

  return (
    <div className='space-y-3'>
      <div className='text-sm font-medium'>Quick Status</div>

      {/* HP Status */}
      <div className='flex items-center justify-between text-xs'>
        <div className='flex items-center gap-1'>
          <Heart
            size={12}
            className={
              hpPercentage <= 25
                ? 'text-destructive'
                : hpPercentage <= 50
                  ? 'text-chart-4'
                  : 'text-chart-2'
            }
          />
          <span>Health</span>
        </div>
        <span className='font-mono'>
          {hp}/{maxHP}
        </span>
      </div>

      {/* Armor */}
      <div className='flex items-center justify-between text-xs'>
        <div className='flex items-center gap-1'>
          <Shield size={12} className='text-primary' />
          <span>Armor</span>
        </div>
        <span className='font-mono'>{armor}</span>
      </div>

      {/* Load Warning */}
      {loadPercentage >= 80 && (
        <div className='flex items-center gap-2 text-xs text-chart-4'>
          <AlertTriangle size={12} />
          <span>
            Heavy load ({load}/{maxLoad})
          </span>
        </div>
      )}
    </div>
  )
}

export const SmartContextPanel: React.FC<SmartContextPanelProps> = ({
  character,
  gameMode,
  theme,
  chronicleEnabled,
  className = '',
}) => {
  const [suggestions, setSuggestions] = useState<Suggestion[]>([])
  const [currentSituation, setCurrentSituation] = useState('')
  const [confidence, setConfidence] = useState(75)

  // Generate contextual suggestions based on game state
  const generateSuggestions = useMemo(() => {
    const newSuggestions: Suggestion[] = []

    // Health-based suggestions
    const hpPercentage =
      ((character.hitPoints?.current || 0) / (character.hitPoints?.max || 1)) *
      100
    if (hpPercentage <= 25) {
      newSuggestions.push({
        id: 'low-hp-warning',
        type: 'warning',
        title: 'Low Health!',
        description: 'Consider healing or defensive actions',
        icon: Heart,
        priority: 'high',
        action: {
          label: 'Find Healing',
          onClick: () => logger.info('smart_context_heal_suggestion', { characterId: character.id }),
        },
      })
    }

    // Load-based suggestions
    const loadPercentage =
      ((character.load?.current || 0) / (character.load?.max || 10)) * 100
    if (loadPercentage >= 80) {
      newSuggestions.push({
        id: 'heavy-load-tip',
        type: 'tip',
        title: 'Heavy Load',
        description: 'You may want to drop some items or find storage',
        icon: AlertTriangle,
        priority: 'medium',
      })
    }

    // Game mode specific suggestions
    switch (gameMode) {
      case 'combat':
        newSuggestions.push({
          id: 'combat-tip',
          type: 'tip',
          title: 'In Combat',
          description: 'Consider your positioning and action economy',
          icon: Target,
          priority: 'medium',
        })
        break

      case 'exploration':
        newSuggestions.push({
          id: 'exploration-opportunity',
          type: 'opportunity',
          title: 'Explore Wisely',
          description: 'Look for secrets and gather information',
          icon: Eye,
          priority: 'low',
        })
        break

      case 'social':
        newSuggestions.push({
          id: 'social-tip',
          type: 'opportunity',
          title: 'Social Interaction',
          description: 'This could be a chance to build bonds or gather intel',
          icon: Users,
          priority: 'medium',
        })
        break
    }

    // Chronicle suggestions
    if (chronicleEnabled) {
      newSuggestions.push({
        id: 'chronicle-reminder',
        type: 'chronicle',
        title: 'Chronicle Opportunity',
        description: 'Recent actions deserve a story entry',
        icon: BookOpen,
        priority: 'low',
        action: {
          label: 'Add to Chronicle',
          onClick: () => logger.info('smart_context_open_chronicle', { characterId: character.id }),
        },
      })
    }

    return newSuggestions
  }, [character, gameMode, chronicleEnabled])

  // Update suggestions when game state changes
  useEffect(() => {
    setSuggestions(generateSuggestions)
  }, [generateSuggestions])

  // Update situation analysis
  useEffect(() => {
    const situations = {
      combat: 'Engaged in dangerous combat',
      exploration: 'Exploring unknown territory',
      social: 'In conversation with NPCs',
      rest: 'Taking time to rest and recover',
    }

    setCurrentSituation(situations[gameMode])

    // Mock confidence calculation based on character state
    const hpPercentage =
      ((character.hitPoints?.current || 0) / (character.hitPoints?.max || 1)) *
      100
    const baseConfidence = hpPercentage > 50 ? 80 : 60
    setConfidence(baseConfidence + Math.floor(Math.random() * 20))
  }, [gameMode, character])

  const dismissSuggestion = (id: string) => {
    setSuggestions((prev) => prev.filter((s) => s.id !== id))
  }

  const cardVariant =
    theme === 'combat'
      ? 'elevated'
      : theme === 'dungeon'
        ? 'parchment'
        : theme === 'tavern'
          ? 'magical'
          : 'glass'

  return (
    <Card
      variant={cardVariant}
      className={`h-full overflow-y-auto ${className}`}
    >
      <CardHeader className='pb-3'>
        <CardTitle className='flex items-center gap-2 text-sm'>
          <Brain size={16} className='text-primary' />
          Smart Assistant
        </CardTitle>
      </CardHeader>

      <CardContent className='space-y-4'>
        {/* Situation Analysis */}
        <SituationBar
          situation={currentSituation}
          confidence={confidence}
          gameMode={gameMode}
        />

        {/* Quick Character Stats */}
        <QuickStats character={character} />

        {/* Contextual Suggestions */}
        <div className='space-y-3'>
          <div className='flex items-center justify-between'>
            <span className='text-sm font-medium'>Suggestions</span>
            <Badge variant='secondary' className='text-xs'>
              {suggestions.length}
            </Badge>
          </div>

          <div className='space-y-2 max-h-64 overflow-y-auto'>
            <AnimatePresence>
              {suggestions.length === 0 ? (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className='text-center text-xs text-muted-foreground py-4'
                >
                  <Lightbulb size={16} className='mx-auto mb-2 opacity-50' />
                  <p>No suggestions at the moment</p>
                  <p>Keep playing to get smart tips!</p>
                </motion.div>
              ) : (
                suggestions.map((suggestion) => (
                  <SuggestionCard
                    key={suggestion.id}
                    suggestion={suggestion}
                    onDismiss={dismissSuggestion}
                  />
                ))
              )}
            </AnimatePresence>
          </div>
        </div>

        {/* Chronicle Integration Status */}
        <div className='pt-3 border-t border-border'>
          <div className='flex items-center justify-between text-xs'>
            <span className='text-muted-foreground '>Chronicle</span>
            <div className='flex items-center gap-1'>
              <div
                className={`w-2 h-2 rounded-full ${chronicleEnabled ? 'bg-chart-2' : 'bg-gray-400'}`}
              />
              <span className='text-muted-foreground'>
                {chronicleEnabled ? 'Active' : 'Disabled'}
              </span>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

export default SmartContextPanel

/**
 * MagicalEffects Component for ZimboMate V2
 * Ambient magical particles and effects around the spell book
 */

import { AnimatePresence, motion } from 'framer-motion'
import { Sparkles } from 'lucide-react'
import React, { useEffect, useState } from 'react'

interface Particle {
  id: string
  x: number
  y: number
  size: number
  color: string
  duration: number
  delay: number
}

interface MagicalEffectsProps {
  isActive?: boolean
  intensity?: 'low' | 'medium' | 'high'
  spellSchool?: string
  className?: string
}

export function MagicalEffects({
  isActive = true,
  intensity = 'medium',
  spellSchool,
  className = '',
}: MagicalEffectsProps) {
  const [particles, setParticles] = useState<Particle[]>([])

  const getSchoolColor = (school?: string) => {
    const colors = {
      abjuration: '#3b82f6',
      conjuration: '#10b981',
      divination: '#f59e0b',
      enchantment: '#ec4899',
      evocation: '#ef4444',
      illusion: '#8b5cf6',
      necromancy: '#6b7280',
      transmutation: '#f97316',
    }
    return school ? colors[school.toLowerCase()] || '#d4af37' : '#d4af37'
  }

  const getParticleCount = () => {
    switch (intensity) {
      case 'low':
        return 8
      case 'medium':
        return 15
      case 'high':
        return 25
      default:
        return 15
    }
  }

  useEffect(() => {
    if (!isActive) {
      setParticles([])
      return
    }

    const generateParticles = () => {
      const newParticles: Particle[] = []
      const count = getParticleCount()
      const color = getSchoolColor(spellSchool)

      for (let i = 0; i < count; i++) {
        newParticles.push({
          id: `particle-${i}-${Date.now()}`,
          x: Math.random() * 100,
          y: Math.random() * 100,
          size: Math.random() * 4 + 2,
          color,
          duration: Math.random() * 3 + 2,
          delay: Math.random() * 2,
        })
      }

      setParticles(newParticles)
    }

    generateParticles()
    const interval = setInterval(generateParticles, 5000)

    return () => clearInterval(interval)
  }, [isActive, intensity, spellSchool])

  if (!isActive) return null

  return (
    <div
      className={`absolute inset-0 pointer-events-none overflow-hidden ${className}`}
    >
      {/* Ambient magical glow */}
      <motion.div
        className='absolute inset-0 opacity-30'
        animate={{
          background: [
            `radial-gradient(circle at 20% 20%, ${getSchoolColor(spellSchool)}20 0%, transparent 50%)`,
            `radial-gradient(circle at 80% 80%, ${getSchoolColor(spellSchool)}20 0%, transparent 50%)`,
            `radial-gradient(circle at 50% 50%, ${getSchoolColor(spellSchool)}20 0%, transparent 50%)`,
          ],
        }}
        transition={{
          duration: 8,
          repeat: Infinity,
          ease: 'easeInOut',
        }}
      />

      {/* Floating particles */}
      <AnimatePresence>
        {particles.map((particle) => (
          <motion.div
            key={particle.id}
            className='absolute'
            style={{
              left: `${particle.x}%`,
              top: `${particle.y}%`,
            }}
            initial={{
              opacity: 0,
              scale: 0,
              rotate: 0,
            }}
            animate={{
              opacity: [0, 1, 1, 0],
              scale: [0, 1, 1.2, 0],
              rotate: 360,
              x: [0, Math.random() * 40 - 20],
              y: [0, Math.random() * 40 - 20],
            }}
            transition={{
              duration: particle.duration,
              delay: particle.delay,
              repeat: Infinity,
              ease: 'easeInOut',
            }}
          >
            <Sparkles size={particle.size} style={{ color: particle.color }} />
          </motion.div>
        ))}
      </AnimatePresence>

      {/* Corner magical effects */}
      <motion.div
        className='absolute top-4 left-4'
        animate={{
          rotate: [0, 360],
          scale: [1, 1.1, 1],
        }}
        transition={{
          duration: 6,
          repeat: Infinity,
          ease: 'easeInOut',
        }}
      >
        <Sparkles
          size={24}
          style={{ color: getSchoolColor(spellSchool) }}
          className='opacity-60'
        />
      </motion.div>

      <motion.div
        className='absolute top-4 right-4'
        animate={{
          rotate: [360, 0],
          scale: [1, 1.2, 1],
        }}
        transition={{
          duration: 8,
          repeat: Infinity,
          ease: 'easeInOut',
          delay: 1,
        }}
      >
        <Sparkles
          size={20}
          style={{ color: getSchoolColor(spellSchool) }}
          className='opacity-50'
        />
      </motion.div>

      <motion.div
        className='absolute bottom-4 left-4'
        animate={{
          rotate: [0, -360],
          scale: [1, 1.15, 1],
        }}
        transition={{
          duration: 7,
          repeat: Infinity,
          ease: 'easeInOut',
          delay: 2,
        }}
      >
        <Sparkles
          size={18}
          style={{ color: getSchoolColor(spellSchool) }}
          className='opacity-40'
        />
      </motion.div>

      <motion.div
        className='absolute bottom-4 right-4'
        animate={{
          rotate: [360, 0],
          scale: [1, 1.3, 1],
        }}
        transition={{
          duration: 9,
          repeat: Infinity,
          ease: 'easeInOut',
          delay: 3,
        }}
      >
        <Sparkles
          size={22}
          style={{ color: getSchoolColor(spellSchool) }}
          className='opacity-70'
        />
      </motion.div>

      {/* Pulsing magical aura */}
      <motion.div
        className='absolute inset-4 border border-current rounded-lg opacity-20'
        style={{ color: getSchoolColor(spellSchool) }}
        animate={{
          opacity: [0.1, 0.3, 0.1],
          scale: [1, 1.02, 1],
        }}
        transition={{
          duration: 4,
          repeat: Infinity,
          ease: 'easeInOut',
        }}
      />
    </div>
  )
}

/**
 * SpellBook Component for ZimboMate V2
 * Main animated spell book interface with magical effects
 */

import * as Dialog from '@radix-ui/react-dialog'
import { AnimatePresence, motion } from 'framer-motion'
import React, { useCallback, useEffect, useState } from 'react'
import { useKeyboardShortcuts } from '../../../hooks/useKeyboardShortcuts'
import { useSpells } from '../../../hooks/useSpells'
import { MagicalEffects } from './MagicalEffects'
import { PageNavigation } from './PageNavigation'
import { SpellBookPage } from './SpellBookPage'
import { SpellDetails } from './SpellDetails'
import { SpellList } from './SpellList'
import { SpellSearch } from './SpellSearch'
import { SpellSlotTracker } from './SpellSlotTracker'

interface SpellBookProps {
  characterId?: string
  isOpen: boolean
  onClose: () => void
  theme?: 'fantasy' | 'dark' | 'light'
  enableAnimations?: boolean
  enableAudio?: boolean
  onSpellCast?: (spell: any, level: number) => void
  onSpellPrepared?: (spell: any) => void
  onSpellUnprepared?: (spell: any) => void
}

export function SpellBook({
  characterId,
  isOpen,
  onClose,
  theme: _theme = 'fantasy',
  enableAnimations = true,
  enableAudio: _enableAudio = true,
  onSpellCast,
  onSpellPrepared,
  onSpellUnprepared: _onSpellUnprepared,
}: SpellBookProps) {
  // Spell management
  const {
    allSpells,
    preparedSpells,
    spellSlots,
    castSpell,
    prepareSpell,
    unprepareSpell: _unprepareSpell,
    longRest,
    shortRest: _shortRest,
    isCasting,
    character: _character,
  } = useSpells(characterId)

  // UI state
  const [currentPage, setCurrentPage] = useState(0)
  const [selectedSpell, setSelectedSpell] = useState<any>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedSchool, setSelectedSchool] = useState<string | null>(null)
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null)
  const [isAnimating, setIsAnimating] = useState(false)

  const pages = ['spells', 'details', 'slots', 'prepared']
  const totalPages = pages.length

  // Page navigation with animation
  const handlePageChange = useCallback(
    (newPage: number) => {
      if (newPage === currentPage || isAnimating) return

      setIsAnimating(true)

      setTimeout(() => {
        setCurrentPage(newPage)
        setIsAnimating(false)
      }, 400)
    },
    [currentPage, isAnimating],
  )

  // Spell actions
  const handleSpellSelect = useCallback(
    (spell: any) => {
      setSelectedSpell(spell)
      if (currentPage !== 1) {
        handlePageChange(1) // Go to details page
      }
    },
    [currentPage, handlePageChange],
  )

  const handleSpellPrepare = useCallback(
    async (spellId: string) => {
      const spell = allSpells.find((s) => s.id === spellId)
      if (!spell) return

      try {
        prepareSpell(spellId)
        onSpellPrepared?.(spell)
      } catch (error) {
        console.error('Failed to prepare spell:', error)
      }
    },
    [allSpells, prepareSpell, onSpellPrepared],
  )

  const handleSpellCast = useCallback(
    async (spellId: string, level: number) => {
      const spell = allSpells.find((s) => s.id === spellId)
      if (!spell) return

      try {
        await castSpell(spellId, {
          upcast: level > spell.level,
        })
        onSpellCast?.(spell, level)
      } catch (error) {
        console.error('Failed to cast spell:', error)
      }
    },
    [allSpells, castSpell, onSpellCast],
  )

  // Search and filter functions
  const handleClearFilters = useCallback(() => {
    setSearchQuery('')
    setSelectedSchool(null)
    setSelectedLevel(null)
  }, [])

  const handleSlotRefresh = useCallback(() => {
    longRest()
  }, [longRest])

  // Keyboard shortcuts
  useKeyboardShortcuts({
    ArrowLeft: () => currentPage > 0 && handlePageChange(currentPage - 1),
    ArrowRight: () =>
      currentPage < totalPages - 1 && handlePageChange(currentPage + 1),
    Escape: onClose,
    1: () => handlePageChange(0),
    2: () => handlePageChange(1),
    3: () => handlePageChange(2),
    4: () => handlePageChange(3),
  })

  // Auto-select first spell when opening spells page
  useEffect(() => {
    if (currentPage === 0 && allSpells.length > 0 && !selectedSpell) {
      setSelectedSpell(allSpells[0])
    }
  }, [currentPage, allSpells, selectedSpell])

  const currentSpellSchool = selectedSpell?.school || 'evocation'

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className='fixed inset-0 bg-black/50 backdrop-blur-sm z-40' />
        <Dialog.Content className='fixed inset-4 md:inset-8 lg:inset-16 z-50 focus:outline-none'>
          <motion.div
            className='spell-book-container w-full h-full relative overflow-hidden'
            initial={{ opacity: 0, scale: 0.9, rotateX: -15 }}
            animate={{ opacity: 1, scale: 1, rotateX: 0 }}
            exit={{ opacity: 0, scale: 0.9, rotateX: -15 }}
            transition={{ duration: 0.5, ease: 'easeOut' }}
          >
            {/* Magical effects overlay */}
            <MagicalEffects
              isActive={enableAnimations}
              intensity='medium'
              spellSchool={currentSpellSchool}
            />

            {/* Page navigation */}
            <PageNavigation
              currentPage={currentPage}
              totalPages={totalPages}
              onPageChange={handlePageChange}
              onClose={onClose}
            />

            {/* Book pages */}
            <div className='flex h-full pt-16'>
              {/* Left page */}
              <div className='flex-1 p-6 relative'>
                <SpellBookPage
                  isVisible={currentPage === 0 || currentPage === 2}
                  isAnimating={isAnimating}
                  animationDirection='left'
                >
                  {currentPage === 0 && (
                    <div className='h-full flex flex-col'>
                      <SpellSearch
                        searchQuery={searchQuery}
                        onSearchChange={setSearchQuery}
                        selectedSchool={selectedSchool}
                        onSchoolChange={setSelectedSchool}
                        selectedLevel={selectedLevel}
                        onLevelChange={setSelectedLevel}
                        onClearFilters={handleClearFilters}
                        className='mb-4'
                      />
                      <SpellList
                        spells={allSpells}
                        selectedSpell={selectedSpell}
                        onSpellSelect={handleSpellSelect}
                        onSpellPrepare={handleSpellPrepare}
                        onSpellCast={handleSpellCast}
                        searchQuery={searchQuery}
                        selectedSchool={selectedSchool}
                        selectedLevel={selectedLevel}
                        className='flex-1'
                      />
                    </div>
                  )}

                  {currentPage === 2 && (
                    <SpellSlotTracker
                      slots={spellSlots.reduce(
                        (acc, slot) => {
                          acc[slot.level] = {
                            total: slot.total,
                            used: slot.used,
                          }
                          return acc
                        },
                        {} as Record<number, { total: number; used: number }>,
                      )}
                      onRefresh={handleSlotRefresh}
                      className='h-full'
                    />
                  )}
                </SpellBookPage>
              </div>

              {/* Book spine */}
              <div className='w-4 bg-gradient-to-b from-gold-600 to-gold-800 relative'>
                <div className='absolute inset-y-0 left-0 w-1 bg-gold-400' />
                <div className='absolute inset-y-0 right-0 w-1 bg-gold-900' />
              </div>

              {/* Right page */}
              <div className='flex-1 p-6 relative'>
                <SpellBookPage
                  isVisible={currentPage === 1 || currentPage === 3}
                  isAnimating={isAnimating}
                  animationDirection='right'
                >
                  {currentPage === 1 && (
                    <SpellDetails
                      spell={selectedSpell}
                      onCast={handleSpellCast}
                      onPrepare={handleSpellPrepare}
                      className='h-full'
                    />
                  )}

                  {currentPage === 3 && (
                    <SpellList
                      spells={preparedSpells}
                      selectedSpell={selectedSpell}
                      onSpellSelect={handleSpellSelect}
                      onSpellPrepare={handleSpellPrepare}
                      onSpellCast={handleSpellCast}
                      searchQuery=''
                      selectedSchool={null}
                      selectedLevel={null}
                      className='h-full'
                    />
                  )}
                </SpellBookPage>
              </div>
            </div>

            {/* Loading overlay */}
            <AnimatePresence>
              {isCasting && (
                <motion.div
                  className='absolute inset-0 bg-magic-500/20 backdrop-blur-sm flex items-center justify-center z-10'
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                >
                  <motion.div
                    className='text-display-md font-display text-accent'
                    animate={{
                      scale: [1, 1.1, 1],
                      opacity: [0.7, 1, 0.7],
                    }}
                    transition={{
                      duration: 1,
                      repeat: Infinity,
                      ease: 'easeInOut',
                    }}
                  >
                    Casting Spell...
                  </motion.div>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/**
 * Stat Roller Component
 *
 * Specialized dice roller for attribute tests (STR, DEX, CON, INT, WIS, CHA).
 * Automatically integrates with Chronicle system to prompt "Why did you roll DEX?"
 * type questions after each roll.
 */

import { motion } from 'framer-motion'
import {
