  Eye, // WIS
  Heart, // CON
  Sparkles, // CHA
  Wind, // DEX
  Zap, // STR
} from 'lucide-react'
import React, { useState } from 'react'
import { Button } from '../ui'
import { ChronicleEnabledDiceRoller } from './ChronicleEnabledDiceRoller'

export type Stat = 'STR' | 'DEX' | 'CON' | 'INT' | 'WIS' | 'CHA'

interface StatInfo {
  name: string
  fullName: string
  description: string
  icon: React.ReactNode
  examples: string[]
  color: string
}

