    icon: <Wind size={16} />,
    examples: [
      'Dodging attacks',
      'Sneaking quietly',
      'Picking locks',
      'Aiming accurately',
    ],
    color: 'text-chart-2',
  },
  CON: {
    name: 'CON',
    fullName: 'Constitution',
    description: 'Endurance and physical resilience',
    icon: <Heart size={16} />,
    examples: [
      'Resisting poison',
      'Enduring harsh weather',
      'Holding breath',
      'Fighting fatigue',
    ],
