      animate={{ opacity: 1, y: 0 }}
      className='mt-4 p-4 bg-muted/50  rounded-lg'
    >
      <div className='text-sm font-medium mb-2 flex items-center gap-2'>
        <span className={info.color}>{info.icon}</span>
        <span>
          Common
          {info.fullName} uses:
        </span>
      </div>
