}

/**
 * XP Award Modal - Modal dialog for awarding experience points to characters
 */

import type { Character } from '../../models/Character'
import * as Dialog from '@radix-ui/react-dialog'
import { Star, Trophy, Users, X } from 'lucide-react'
import React, { useEffect, useState } from 'react'
import { useCharacterStore } from '../../stores/characterStore'
import { Button, Card, CardContent, CardHeader, CardTitle } from '../ui'
import { Input } from '../ui/Input'

interface XPAwardModalProps {
  isOpen: boolean
  onClose: () => void
  onAwarded?: (totalXPAwarded: number, charactersAffected: number) => void
}

interface CharacterXPAward {
  character: Character
  xpAmount: number
  selected: boolean
  reason: string
}

const XP_PRESETS = [
  {
    label: 'Minor Achievement',
    amount: 1,
    description: 'Small progress or minor success',
  },
  {
    label: 'Significant Progress',
    amount: 2,
    description: 'Good roleplay or problem solving',
  },
  {
    label: 'Major Milestone',
    amount: 3,
    description: 'Completing major objectives',
  },
  {
    label: 'Session Completion',
    amount: 1,
    description: 'End of session bonus',
  },
]

export const XPAwardModal: React.FC<XPAwardModalProps> = ({
  isOpen,
  onClose,
  onAwarded,
}) => {
  const characters = useCharacterStore((state) => state.characters)
  const addXP = useCharacterStore((state) => state.addXP)

  const [characterAwards, setCharacterAwards] = useState<CharacterXPAward[]>([])
  const [globalXP, setGlobalXP] = useState<number>(1)
  const [globalReason, setGlobalReason] = useState<string>('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [awardMode, setAwardMode] = useState<'global' | 'individual'>('global')

  // Initialize character awards when modal opens
  useEffect(() => {
    if (isOpen) {
      setCharacterAwards(
        characters.map((character) => ({
          character,
          xpAmount: 1,
          selected: true,
          reason: '',
        })),
      )
      setGlobalXP(1)
      setGlobalReason('')
      setAwardMode('global')
    }
  }, [isOpen, characters])

  const handleGlobalXPChange = (amount: number) => {
    setGlobalXP(amount)
    setCharacterAwards((prev) =>
      prev.map((award) => ({
        ...award,
        xpAmount: amount,
      })),
    )
  }

  const handleIndividualXPChange = (characterId: string, amount: number) => {
    setCharacterAwards((prev) =>
      prev.map((award) =>
        award.character.id === characterId
          ? { ...award, xpAmount: Math.max(0, Math.min(10, amount)) }
          : award,
      ),
    )
  }

  const handleToggleCharacter = (characterId: string) => {
    setCharacterAwards((prev) =>
      prev.map((award) =>
        award.character.id === characterId
          ? { ...award, selected: !award.selected }
          : award,
      ),
    )
  }

  const handleReasonChange = (characterId: string, reason: string) => {
    setCharacterAwards((prev) =>
      prev.map((award) =>
        award.character.id === characterId ? { ...award, reason } : award,
      ),
    )
  }

  const handlePresetXP = (amount: number, description: string) => {
    if (awardMode === 'global') {
      handleGlobalXPChange(amount)
      setGlobalReason(description)
    } else {
      setCharacterAwards((prev) =>
        prev.map((award) => ({
          ...award,
          xpAmount: amount,
          reason: description,
        })),
      )
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const selectedAwards = characterAwards.filter(
      (award) => award.selected && award.xpAmount > 0,
    )

    if (selectedAwards.length === 0) {
      return
    }

    setIsSubmitting(true)

    try {
      const totalXPAwarded = selectedAwards.reduce(
        (sum, award) => sum + award.xpAmount,
        0,
      )

      // Award XP to each selected character
      for (const award of selectedAwards) {
        const reason =
          awardMode === 'global'
            ? globalReason || 'Session XP Award'
            : award.reason || 'Individual XP Award'

        addXP(award.character.id, award.xpAmount, 'Session Award', reason)
      }

      onAwarded?.(totalXPAwarded, selectedAwards.length)
      onClose()
    } catch (error) {
      console.error('Error awarding XP:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const selectedCharacters = characterAwards.filter((award) => award.selected)
  const totalXPToAward = selectedCharacters.reduce(
    (sum, award) => sum + award.xpAmount,
    0,
  )

  return (
    <Dialog.Root open={isOpen} onOpenChange={onClose}>
      <Dialog.Portal>
        <Dialog.Overlay className='fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0' />
        <Dialog.Content className='fixed left-1/2 top-1/2 z-50 w-full max-w-2xl -translate-x-1/2 -translate-y-1/2 border shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] rounded-lg max-h-[90vh] overflow-y-auto'>
          <Card variant='magical'>
            <CardHeader className='flex flex-row items-center justify-between space-y-0 pb-4'>
              <div className='flex items-center gap-3'>
                <Trophy className='h-5 w-5 text-primary' />
                <CardTitle className='text-xl'>
                  Award Experience Points
                </CardTitle>
              </div>
              <Dialog.Close asChild>
                <Button variant='ghost' size='sm' className='h-8 w-8 p-0'>
                  <X className='h-4 w-4' />
                </Button>
              </Dialog.Close>
            </CardHeader>

            <CardContent>
              <form onSubmit={handleSubmit} className='space-y-6'>
                {/* Award Mode Toggle */}
                <div className='space-y-3'>
                  <label className='text-sm font-medium'>Award Method</label>
                  <div className='flex gap-2'>
                    <Button
                      type='button'
                      variant={awardMode === 'global' ? 'primary' : 'ghost'}
                      size='sm'
                      onClick={() => setAwardMode('global')}
                    >
                      <Users size={16} />
                      Global Award
                    </Button>
                    <Button
                      type='button'
                      variant={awardMode === 'individual' ? 'primary' : 'ghost'}
                      size='sm'
                      onClick={() => setAwardMode('individual')}
                    >
                      <Star size={16} />
                      Individual Awards
                    </Button>
                  </div>
                </div>

                {/* XP Presets */}
                <div className='space-y-3'>
                  <label className='text-sm font-medium'>Quick Presets</label>
                  <div className='grid grid-cols-2 gap-2'>
                    {XP_PRESETS.map((preset) => (
                      <Button
                        key={preset.label}
                        type='button'
                        variant='outline'
                        size='sm'
                        className='justify-start h-auto p-3'
                        onClick={() =>
                          handlePresetXP(preset.amount, preset.description)
                        }
                      >
                        <div className='text-left'>
                          <div className='font-medium'>{preset.label}</div>
                          <div className='text-xs text-muted-foreground'>
                            {preset.amount} XP - {preset.description}
                          </div>
                        </div>
                      </Button>
                    ))}
                  </div>
                </div>

                {/* Global Settings */}
                {awardMode === 'global' && (
                  <div className='space-y-4'>
                    <div className='grid grid-cols-2 gap-4'>
                      <div className='space-y-2'>
                        <label className='text-sm font-medium'>XP Amount</label>
                        <Input
                          type='number'
                          value={globalXP}
                          onChange={(e) =>
                            handleGlobalXPChange(
                              Number.parseInt(e.target.value) || 0,
                            )
                          }
                          min='0'
                          max='10'
                        />
                      </div>
                      <div className='space-y-2'>
                        <label className='text-sm font-medium'>Total XP</label>
                        <div className='px-3 py-2 bg-muted rounded-lg text-sm font-medium'>
                          {totalXPToAward} XP to
                          {selectedCharacters.length} character
                          {selectedCharacters.length !== 1 ? 's' : ''}
                        </div>
                      </div>
                    </div>
                    <div className='space-y-2'>
                      <label className='text-sm font-medium'>Reason</label>
                      <Input
                        value={globalReason}
                        onChange={(e) => setGlobalReason(e.target.value)}
                        placeholder='Why are you awarding this XP?'
                      />
                    </div>
                  </div>
                )}

                {/* Character Selection */}
                <div className='space-y-3'>
                  <label className='text-sm font-medium flex items-center gap-2'>
                    <Users size={16} />
                    Characters ({selectedCharacters.length}/
                    {characterAwards.length} selected)
                  </label>

                  {characterAwards.length === 0 ? (
                    <div className='text-center py-6 text-muted-foreground'>
                      <Users size={32} className='mx-auto mb-2 opacity-50' />
                      <p>No characters found</p>
                      <p className='text-xs'>
                        Create characters first to award XP
                      </p>
                    </div>
                  ) : (
                    <div className='space-y-3'>
                      {characterAwards.map((award) => (
                        <Card key={award.character.id} variant='surface'>
                          <CardContent className='p-4 pt-4'>
                            <div className='flex items-center gap-4'>
                              <input
                                type='checkbox'
                                checked={award.selected}
                                onChange={() =>
                                  handleToggleCharacter(award.character.id)
                                }
                                className='h-4 w-4'
                              />
                              <div className='flex-1'>
                                <div className='font-medium'>
                                  {award.character.name}
                                </div>
                                <div className='text-sm text-muted-foreground'>
                                  Level {award.character.level} ΓÇó Current XP:{' '}
                                  {award.character.xp}
                                </div>
                              </div>

                              {awardMode === 'individual' && (
                                <div className='flex gap-2 items-center'>
                                  <Input
                                    type='number'
                                    value={award.xpAmount}
                                    onChange={(e) =>
                                      handleIndividualXPChange(
                                        award.character.id,
                                        Number.parseInt(e.target.value) || 0,
                                      )
                                    }
                                    min='0'
                                    max='10'
                                    className='w-20'
                                  />
                                  <span className='text-sm'>XP</span>
                                </div>
                              )}

                              {awardMode === 'global' && (
                                <div className='text-sm font-medium'>
                                  +{award.xpAmount} XP
                                </div>
                              )}
                            </div>

                            {awardMode === 'individual' && award.selected && (
                              <div className='mt-3'>
                                <Input
                                  value={award.reason}
                                  onChange={(e) =>
                                    handleReasonChange(
                                      award.character.id,
                                      e.target.value,
                                    )
                                  }
                                  placeholder="Reason for this character's XP..."
                                  className='text-sm'
                                />
                              </div>
                            )}
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                  )}
                </div>

                {/* Actions */}
                <div className='flex items-center justify-between pt-4'>
                  <div className='text-sm text-muted-foreground'>
                    {selectedCharacters.length > 0 ? (
                      <>
                        Awarding{' '}
                        <span className='font-medium'>
                          {totalXPToAward} total XP
                        </span>{' '}
                        to{' '}
                        <span className='font-medium'>
                          {selectedCharacters.length}
                        </span>{' '}
                        character
                        {selectedCharacters.length !== 1 ? 's' : ''}
                      </>
                    ) : (
                      'Select characters to award XP'
                    )}
                  </div>
                  <div className='flex gap-3'>
                    <Button
                      type='button'
                      variant='ghost'
                      onClick={onClose}
                      disabled={isSubmitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      type='submit'
                      variant='primary'
                      disabled={
                        isSubmitting ||
                        selectedCharacters.length === 0 ||
                        totalXPToAward === 0
                      }
                      className='min-w-20'
                    >
                      {isSubmitting ? 'Awarding...' : 'Award XP'}
                    </Button>
                  </div>
                </div>
              </form>
            </CardContent>
          </Card>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

import type {
  XPEntry,
  XPNotification,
} from '../../services/XPIntegrationService'
import { AnimatePresence, motion } from 'framer-motion'
import {
  AlertTriangle,
  Award,
  BarChart3,
  Calendar,
  Heart,
  Shield,
  Star,
  TrendingUp,
  Zap,
} from 'lucide-react'
import React, { useEffect, useState } from 'react'
import { getXPThreshold } from '../../models/Character'
import { xpIntegrationService } from '../../services/XPIntegrationService'
import { useCharacterStore } from '../../stores/characterStore'
import { Badge, Button, Card, CardContent } from '../ui'

interface XPProgressTrackerProps {
  characterId?: string
  compact?: boolean
  showNotifications?: boolean
}

export const XPProgressTracker: React.FC<XPProgressTrackerProps> = ({
  characterId,
  compact = false,
  showNotifications = true,
}) => {
  const { getActiveCharacter, levelUpCharacter } = useCharacterStore()
  const [xpEntries, setXpEntries] = useState<XPEntry[]>([])
  const [notifications, setNotifications] = useState<XPNotification[]>([])
  const [showHistory, setShowHistory] = useState(false)
  const [analytics, setAnalytics] = useState<any>(null)

  const activeCharacter = getActiveCharacter()
  const effectiveCharacterId = characterId || activeCharacter?.id

  useEffect(() => {
    if (!effectiveCharacterId) return

    // Load XP data
    const entries = xpIntegrationService.getXPEntries(effectiveCharacterId, 20)
    const analyticsData =
      xpIntegrationService.getAnalytics(effectiveCharacterId)

    setXpEntries(entries)
    setAnalytics(analyticsData)

    // Set up notification listener
    const handleNotification = (notification: XPNotification) => {
      if (notification.characterId === effectiveCharacterId) {
        setNotifications((prev) => [notification, ...prev.slice(0, 4)]) // Keep last 5
      }
    }

    xpIntegrationService.addNotificationListener(handleNotification)

    // Load existing notifications
    const existingNotifications = xpIntegrationService
      .getNotifications()
      .filter((n) => n.characterId === effectiveCharacterId)
    setNotifications(existingNotifications)

    return () => {
      xpIntegrationService.removeNotificationListener(handleNotification)
    }
  }, [effectiveCharacterId])

  const handleLevelUp = () => {
    if (effectiveCharacterId) {
      levelUpCharacter(effectiveCharacterId)
    }
  }

  const handleDismissNotification = (notificationId: string) => {
    xpIntegrationService.clearNotification(notificationId)
    setNotifications((prev) => prev.filter((n) => n.id !== notificationId))
  }

  const getSourceIcon = (sourceId: string) => {
    switch (sourceId) {
      case 'failure':
        return <AlertTriangle size={14} />
      case 'bond-resolution':
        return <Heart size={14} />
      case 'alignment-good':
      case 'alignment-lawful':
      case 'alignment-neutral':
      case 'alignment-chaotic':
      case 'alignment-evil':
        return <Shield size={14} />
      case 'level-up':
        return <Star size={14} />
      case 'gm-award':
        return <Award size={14} />
      case 'end-of-session':
        return <Calendar size={14} />
      default:
        return <Zap size={14} />
    }
  }

  const getCurrentLevel = (totalXP: number) => {
    // Start at level 1, check if we can level up
    let level = 1
    while (totalXP >= getXPThreshold(level)) {
      level++
    }
    return level
  }

  const getXPToNextLevel = (totalXP: number) => {
    const currentLevel = getCurrentLevel(totalXP)
    const nextThreshold = getXPThreshold(currentLevel)

    if (currentLevel >= 10) return 0 // Max level (arbitrary cap)
    return nextThreshold - totalXP
  }

  const getXPProgress = (totalXP: number) => {
    const currentLevel = getCurrentLevel(totalXP)

    if (currentLevel >= 10) return 100 // Max level

    const prevThreshold =
      currentLevel === 1 ? 0 : getXPThreshold(currentLevel - 1)
    const nextThreshold = getXPThreshold(currentLevel)

    const progress =
      ((totalXP - prevThreshold) / (nextThreshold - prevThreshold)) * 100
    return Math.min(100, Math.max(0, progress))
  }

  if (!effectiveCharacterId || !analytics) {
    return (
      <Card variant='muted'>
        <CardContent className='p-4 text-center'>
          <Star size={32} className='mx-auto text-muted-foreground mb-2' />
          <p className='text-sm text-muted-foreground'>
            Select a character to track XP progress
          </p>
        </CardContent>
      </Card>
    )
  }

  const currentLevel = getCurrentLevel(analytics.totalXP)
  const xpToNext = getXPToNextLevel(analytics.totalXP)
  const progressPercent = getXPProgress(analytics.totalXP)
  const canLevelUp = xpToNext <= 0 && currentLevel < 11

  if (compact) {
    return (
      <Card>
        <CardContent className='p-3'>
          <div className='flex items-center justify-between'>
            <div className='flex items-center gap-3'>
              <div className='flex items-center gap-1'>
                <Star size={16} className='text-primary' />
                <span className='font-semibold'>{analytics.totalXP} XP</span>
              </div>
              <Badge variant='secondary' size='sm'>
                Level {currentLevel}
              </Badge>
            </div>

            {canLevelUp ? (
              <Button variant='primary' size='sm' onClick={handleLevelUp}>
                Level Up!
              </Button>
            ) : (
              <span className='text-xs text-muted-foreground'>
                {xpToNext} to next
              </span>
            )}
          </div>

          <div className='mt-2'>
            <div className='w-full bg-muted rounded-full h-1.5'>
              <motion.div
                className='h-1.5 rounded-full bg-primary'
                initial={{ width: 0 }}
                animate={{ width: `${progressPercent}%` }}
                transition={{ duration: 0.5 }}
              />
            </div>
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className='space-y-4'>
      {/* Notifications */}
      <AnimatePresence>
        {showNotifications &&
          notifications.map((notification) => (
            <motion.div
              key={notification.id}
              initial={{ opacity: 0, y: -20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -20, scale: 0.95 }}
              className='relative'
            >
              <Card
                variant={
                  notification.type === 'level-up' ? 'success' : 'default'
                }
              >
                <CardContent className='p-4'>
                  <div className='flex items-start justify-between'>
                    <div className='flex items-start gap-3'>
                      <div
                        className='w-8 h-8 rounded-full flex items-center justify-center'
                        style={{
                          backgroundColor: notification.entry.source.color,
                          opacity: 0.2,
                        }}
                      >
                        <div style={{ color: notification.entry.source.color }}>
                          {getSourceIcon(notification.entry.source.id)}
                        </div>
                      </div>

                      <div className='flex-1'>
                        <p className='font-medium text-sm'>
                          {notification.message}
                        </p>
                        {notification.actions && (
                          <div className='flex gap-2 mt-2'>
                            {notification.actions.map((action, index) => (
                              <Button
                                key={index}
                                variant='outline'
                                size='sm'
                                onClick={action.action}
                              >
                                {action.label}
                              </Button>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>

                    <button
                      onClick={() => handleDismissNotification(notification.id)}
                      className='text-xs opacity-50 hover:opacity-100 transition-opacity'
                    >
                      Γ£ò
                    </button>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
      </AnimatePresence>

      {/* Main XP Display */}
      <Card variant='magical'>
        <CardContent className='p-6'>
          <div className='space-y-6'>
            {/* Header */}
            <div className='flex items-center justify-between'>
              <div className='flex items-center gap-3'>
                <Star size={24} className='text-primary' />
                <div>
                  <h3 className='text-lg font-display'>Experience Points</h3>
                  <p className='text-sm text-muted-foreground'>
                    Character progression and advancement
                  </p>
                </div>
              </div>

              <Button
                variant='ghost'
                size='sm'
                onClick={() => setShowHistory(!showHistory)}
                className='gap-2'
              >
                <BarChart3 size={16} />
                {showHistory ? 'Hide' : 'Show'} Details
              </Button>
            </div>

            {/* Level and XP Display */}
            <div className='text-center space-y-4'>
              <div className='space-y-2'>
                <div className='text-4xl font-bold font-display'>
                  Level {currentLevel}
                </div>
                <div className='text-xl font-semibold'>
                  {analytics.totalXP} XP
                </div>
              </div>

              {/* Progress Bar */}
              <div className='space-y-2'>
                <div className='flex justify-between text-sm text-muted-foreground'>
                  <span>
                    Progress to Level
                    {currentLevel + 1}
                  </span>
                  <span>{canLevelUp ? 'Ready!' : `${xpToNext} XP needed`}</span>
                </div>

                <div className='w-full bg-muted rounded-full h-3'>
                  <motion.div
                    className='h-3 rounded-full bg-gradient-to-r from-primary to-accent'
                    initial={{ width: 0 }}
                    animate={{ width: `${progressPercent}%` }}
                    transition={{ duration: 1, ease: 'easeOut' }}
                  />
                </div>
              </div>

              {/* Level Up Button */}
              {canLevelUp && (
                <motion.div
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ type: 'spring', stiffness: 300 }}
                >
                  <Button
                    variant='primary'
                    size='lg'
                    onClick={handleLevelUp}
                    className='gap-2'
                  >
                    <TrendingUp size={20} />
                    Level Up to {currentLevel + 1}!
                  </Button>
                </motion.div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Detailed Analytics */}
      <AnimatePresence>
        {showHistory && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className='space-y-4'
          >
            {/* XP Sources */}
            <Card>
              <CardContent className='p-4'>
                <h4 className='font-semibold mb-3'>XP Sources</h4>
                <div className='space-y-2'>
                  {Object.entries(analytics.xpBySource).map(
                    ([sourceId, amount]) => {
                      const source = xpIntegrationService
                        .getXPSources()
                        .find((s) => s.id === sourceId)
                      if (!source || amount === 0) return null

                      return (
                        <div
                          key={sourceId}
                          className='flex items-center justify-between'
                        >
                          <div className='flex items-center gap-2'>
                            <div style={{ color: source.color }}>
                              {getSourceIcon(sourceId)}
                            </div>
                            <span className='text-sm'>{source.name}</span>
                          </div>
                          <Badge variant='secondary' size='sm'>
                            {amount} XP
                          </Badge>
                        </div>
                      )
                    },
                  )}
                </div>
              </CardContent>
            </Card>

            {/* Recent XP History */}
            <Card>
              <CardContent className='p-4'>
                <h4 className='font-semibold mb-3'>Recent XP Gains</h4>
                <div className='space-y-3'>
                  {xpEntries.slice(0, 10).map((entry) => (
                    <div key={entry.id} className='flex items-start gap-3'>
                      <div
                        className='w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5'
                        style={{
                          backgroundColor: entry.source.color,
                          opacity: 0.2,
                        }}
                      >
                        <div style={{ color: entry.source.color }}>
                          {getSourceIcon(entry.source.id)}
                        </div>
                      </div>

                      <div className='flex-1 min-w-0'>
                        <div className='flex items-center justify-between'>
                          <span className='text-sm font-medium'>
                            +{entry.amount} XP
                          </span>
                          <span className='text-xs text-muted-foreground'>
                            {entry.timestamp.toLocaleDateString()}
                          </span>
                        </div>
                        <p className='text-xs text-muted-foreground truncate'>
                          {entry.reason}
                        </p>
                      </div>
                    </div>
                  ))}

                  {xpEntries.length === 0 && (
                    <p className='text-sm text-muted-foreground text-center py-4'>
                      No XP gained yet. Start adventuring!
                    </p>
                  )}
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

