// Helper functions for spellcasting
function isSpellcaster(characterClass?: CharacterClass): boolean {
  return characterClass === 'Wizard' || characterClass === 'Cleric'
}

function requiresDeity(characterClass?: CharacterClass): boolean {
  return characterClass === 'Cleric' || characterClass === 'Paladin'
}

export const CharacterBuilder: React.FC<{ onFinished?: () => void }> = ({
  onFinished,
}) => {
  const { createCharacter, setActiveCharacter } = useCharacterStore()
  const [step, setStep] = useState<StepId>('class')
  const [draft, setDraft] = useState<Draft>(loadDraftFromStorage)

  useEffect(() => {
    if (typeof window === 'undefined') return
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(draft))
  }, [draft])

  const steps: { id: StepId; title: string; desc?: string }[] = [
    { id: 'class', title: 'Choose Class' },
    { id: 'identity', title: 'Identity' },
    { id: 'alignment', title: 'Alignment' },
    { id: 'attributes', title: 'Assign Stats' },
    { id: 'derived', title: 'Derived Values' },
    { id: 'bonds', title: 'Bonds' },
    { id: 'gear', title: 'Starting Gear' },
    { id: 'spellcasting', title: 'Spellcasting' },
    { id: 'review', title: 'Review & Create' },
  ]
  const stepIndex = steps.findIndex((s) => s.id === step)
  const canNext = useMemo(() => {
    switch (step) {
      case 'class':
        return !!draft.class
      case 'identity':
        return !!draft.name && !!draft.race
      case 'alignment':
        return !!draft.alignment
      case 'attributes':
        return true
      case 'derived':
        return true
      case 'bonds':
        return true
      case 'gear':
        return true
      case 'spellcasting': {
        // Skip if not a spellcaster/deity user, or validate required fields
        if (!isSpellcaster(draft.class) && !requiresDeity(draft.class))
          return true
        if (requiresDeity(draft.class) && !draft.deity) return false
        if (
          draft.class === 'Wizard' &&
          (!draft.spellbook || draft.spellbook.length === 0)
        )
          return false
        if (
          draft.class === 'Cleric' &&
          (!draft.spellbook || draft.spellbook.length === 0)
        )
          return false
        return true
      }
      case 'review':
        return true
      default:
        return false
    }
  }, [step, draft])

  const next = () =>
    setStep(steps[Math.min(stepIndex + 1, steps.length - 1)].id)
  const back = () => setStep(steps[Math.max(stepIndex - 1, 0)].id)
  const saveAndExit = () => {
    if (typeof window === 'undefined') return
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(draft))
  }

  const derivedPreview = useMemo(() => {
    if (!draft.class) return null
    const base: Character = {
      id: 'temp',
      name: draft.name || 'Unnamed',
      class: draft.class,
      race: draft.race || 'Human',
      level: 1,
      alignment: draft.alignment || 'Neutral',
      attributes: draft.attributes,
      debilities: {
        weak: false,
        shaky: false,
        sick: false,
        stunned: false,
        confused: false,
        scarred: false,
      },
      hp: { current: 1, max: 1 },
      armor: 0,
      damageDie: getClassDamageDie(draft.class),
      xp: 0,
      load: { current: 0, max: 0 },
      baseLoad: getClassBaseLoad(draft.class),
      coin: 0,
      bonds: [],
      advancements: [],
      knownMoves: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      conditions: [],
    }
    const maxHp = calculateMaxHP(base)
    const maxLoad = calculateMaxLoad(base)
    return { maxHp, maxLoad, damageDie: base.damageDie }
  }, [draft])

  const finalize = () => {
    if (!draft.class || !draft.race || !draft.alignment || !draft.name) return

    const bondTexts = (draft.bonds || [])
      .map((bond) => bond.text?.trim())
      .filter((value): value is string => !!value)

    const timestamp = Date.now()
    const bonds = bondTexts.map((text, i) => ({
      id: `bond-${i + 1}-${timestamp}`,
      text,
      resolved: false,
    }))

    let gearSeeds: GearSeed[] = draft.gear
    if (draft.class) {
      const classGear = CLASS_STARTING_GEAR[draft.class]
      gearSeeds = [...classGear.base]
      if (classGear.choice && draft.gearChoiceIndex !== undefined) {
        gearSeeds.push(...classGear.choice.options[draft.gearChoiceIndex])
      }
    }

    const classSlug = draft.class ? slugify(draft.class) : 'custom'
    const inventory: Item[] = gearSeeds.map((seed, index) =>
      gearSeedToItem(seed, `starter-${classSlug}-${index + 1}-${timestamp}`),
    )

    const newChar = createCharacter({
      name: draft.name,
      look: draft.look,
      class: draft.class,
      race: draft.race,
      level: 1,
      alignment: draft.alignment,
      attributes: draft.attributes,
      debilities: {
        weak: false,
        shaky: false,
        sick: false,
        stunned: false,
        confused: false,
        scarred: false,
      },
      hp: {
        current: derivedPreview?.maxHp || getClassBaseHP(draft.class),
        max: derivedPreview?.maxHp || getClassBaseHP(draft.class),
      },
      armor: 0,
      damageDie: getClassDamageDie(draft.class),
      xp: 0,
      load: {
        current: 0,
        max: derivedPreview?.maxLoad ?? getClassBaseLoad(draft.class),
      },
      baseLoad: getClassBaseLoad(draft.class),
      coin: 0,
      bonds,
      advancements: [],
      knownMoves: STARTING_MOVES[draft.class] || [],
      knownSpells: draft.spellbook || [],
      preparedSpells:
        draft.class === 'Wizard' || draft.class === 'Cleric'
          ? draft.spellbook || []
          : [],
      deity: draft.deity,
      inventory,
      notes: '',
      looks: draft.look || '',
      backstory: '',
    })

    setActiveCharacter(newChar.id)
    if (typeof window !== 'undefined') {
      window.localStorage.removeItem(STORAGE_KEY)
    }
    onFinished?.()
  }

  // eslint-disable-next-line react/no-nested-component-definitions
  const StandardArrayAssign: React.FC = () => {
    const pool = getStandardArray()
    const [assignments, setAssignments] = useState<
      Record<keyof Attributes, number>
    >({
      STR: draft.attributes.STR,
      DEX: draft.attributes.DEX,
      CON: draft.attributes.CON,
      INT: draft.attributes.INT,
      WIS: draft.attributes.WIS,
      CHA: draft.attributes.CHA,
    })

    const used = new Set(Object.values(assignments))
    const remaining = pool.filter((v) => !used.has(v))

    const setVal = (attr: keyof Attributes, value: number) => {
      setAssignments((a) => {
        const prev = { ...a }
        prev[attr] = value
        return prev
      })
    }

    useEffect(() => {
      setDraft((d) => ({ ...d, attributes: assignments as Attributes }))
    }, [assignments])

    return (
      <div className='space-y-4'>
        <div className='text-sm text-muted-foreground'>
          Standard Array:
          {pool.join(', ')}
        </div>
        <div className='grid grid-cols-2 md:grid-cols-3 gap-3'>
          {(Object.keys(assignments) as (keyof Attributes)[]).map((attr) => (
            <Card key={attr} variant='surface'>
              <CardContent className='p-4 pt-4'>
                <div className='flex items-center justify-between mb-2'>
                  <div className='font-medium'>{attr}</div>
                  <Badge variant='secondary'>
                    mod
                    {getAttributeModifier(assignments[attr]) >= 0
                      ? `+${getAttributeModifier(assignments[attr])}`
                      : getAttributeModifier(assignments[attr])}
                  </Badge>
                </div>
                <select
                  className='w-full rounded-md border px-2 py-1 bg-card text-sm'
                  value={assignments[attr]}
                  onChange={(e) => setVal(attr, Number(e.target.value))}
                  aria-label={`Assign value to ${attr}`}
                  title={`Assign value to ${attr}`}
                >
                  {[assignments[attr], ...remaining].map((val) => (
                    <option key={`${attr}-${val}`} value={val}>
                      {val}
                    </option>
                  ))}
                </select>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    )
  }

  return (
    <Card variant='magical'>
      <CardHeader>
        <div className='flex items-center justify-between'>
          <div>
            <CardTitle>Character Builder</CardTitle>
            <CardDescription>
              Create a valid Dungeon World character
            </CardDescription>
          </div>
          <div className='min-w-[160px]'>
            <Progress
              variant='experience'
              value={stepIndex + 1}
              max={steps.length}
              aria-label={`Step ${stepIndex + 1} of ${steps.length}`}
            />
            <p className='mt-1 text-xs text-muted-foreground'>
              Step
              {stepIndex + 1} of
              {steps.length}
            </p>
          </div>
        </div>
      </CardHeader>

      <CardContent>
        {step === 'class' && (
          <div className='space-y-4'>
            <div className='grid grid-cols-2 md:grid-cols-3 gap-3'>
              {ALL_CLASSES.map((cls) => (
                <Button
                  key={cls}
                  variant={draft.class === cls ? 'primary' : 'outline'}
                  onClick={() => {
                    setDraft((d) => {
                      const availableRaces = CLASS_RACIAL_OPTIONS[cls]
                      const currentRace = d.race
                      const newRace = availableRaces.includes(currentRace || '')
                        ? currentRace
                        : availableRaces[0]

                      const availableAlignments = CLASS_ALIGNMENTS[cls]
                      const currentAlignment = d.alignment
                      const newAlignment = availableAlignments.includes(
                        currentAlignment || '',
                      )
                        ? currentAlignment
                        : availableAlignments[0]

                      const newDraft: Draft = {
                        ...d,
                        class: cls,
                        race: newRace,
                        alignment: newAlignment,
                      }

                      // Class-specific attribute requirements
                      if (cls === 'Wizard') {
                        newDraft.attributes = {
                          ...d.attributes,
                          INT: Math.max(d.attributes.INT, 16),
                        }
                      }

                      if (!isSpellcaster(cls)) {
                        newDraft.spellbook = []
                      } else if (
                        cls === 'Cleric' &&
                        (newDraft.spellbook?.length || 0) > 2
                      ) {
                        newDraft.spellbook = (newDraft.spellbook || []).slice(
                          0,
                          2,
                        )
                      } else if (
                        cls === 'Wizard' &&
                        (newDraft.spellbook?.length || 0) > 3
                      ) {
                        newDraft.spellbook = (newDraft.spellbook || []).slice(
                          0,
                          3,
                        )
                      }

                      if (!requiresDeity(cls)) {
                        newDraft.deity = undefined
                      }

                      return newDraft
                    })
                  }}
                >
                  {cls}
                </Button>
              ))}
            </div>
          </div>
        )}

        {step === 'identity' && (
          <div className='space-y-4'>
            <div className='grid md:grid-cols-2 gap-4'>
              <div>
                <label className='text-sm' htmlFor='builder-name'>
                  Name
                </label>
                <Input
                  id='builder-name'
                  value={draft.name}
                  onChange={(e) =>
                    setDraft((d) => ({ ...d, name: e.target.value }))
                  }
                  placeholder="Your hero's name"
                />
              </div>
              <div>
                <label className='text-sm' htmlFor='builder-race'>
                  Race
                </label>
                <select
                  id='builder-race'
                  className='w-full rounded-md border px-2 py-2 bg-card'
                  value={draft.race || ''}
                  onChange={(e) =>
                    setDraft((d) => ({ ...d, race: e.target.value as Race }))
                  }
                  aria-label='Select race'
                  title='Select race'
                >
                  <option value='' disabled>
                    Select race
                  </option>
                  {(draft.class ? CLASS_RACIAL_OPTIONS[draft.class] : []).map(
                    (r) => (
                      <option key={r} value={r}>
                        {r}
                      </option>
                    ),
                  )}
                </select>
              </div>
            </div>
            <div>
              <label className='text-sm' htmlFor='builder-look'>
                Look (appearance)
              </label>
              <Input
                id='builder-look'
                value={draft.look || ''}
                onChange={(e) =>
                  setDraft((d) => ({ ...d, look: e.target.value }))
                }
                placeholder='e.g., Tired eyes, ink-stained hands'
              />
            </div>

            {/* Show racial move for selected class/race */}
            {draft.class &&
              draft.race &&
              RACIAL_MOVES[draft.class]?.[draft.race]?.length > 0 && (
                <Card variant='surface'>
                  <CardContent className='p-4 pt-4'>
                    <div className='space-y-2'>
                      <div className='font-medium text-sm text-primary'>
                        Racial Move
                      </div>
                      {RACIAL_MOVES[draft.class][draft.race].map((move) => (
                        <div
                          key={`${draft.class}-${draft.race}-${slugify(move)}`}
                          className='text-sm text-muted-foreground'
                        >
                          {move}
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
          </div>
        )}

        {step === 'alignment' && (
          <div className='space-y-4'>
            <div className='grid grid-cols-2 md:grid-cols-3 gap-3'>
              {(draft.class ? CLASS_ALIGNMENTS[draft.class] : []).map((a) => (
                <Button
                  key={a}
                  variant={draft.alignment === a ? 'primary' : 'outline'}
                  onClick={() => setDraft((d) => ({ ...d, alignment: a }))}
                >
                  {a}
                </Button>
              ))}
            </div>
            {/* Show alignment restrictions */}
            {draft.class && (
              <div className='text-sm text-muted-foreground'>
                <strong>{draft.class}</strong> can only be:
                {CLASS_ALIGNMENTS[draft.class].join(', ')}
              </div>
            )}
          </div>
        )}

        {step === 'attributes' && (
          <div className='space-y-4'>
            <StandardArrayAssign />
          </div>
        )}

        {step === 'derived' && (
          <div className='grid md:grid-cols-3 gap-4'>
            <Card variant='parchment'>
              <CardContent className='p-4 pt-4'>
                <div className='text-sm text-muted-foreground'>
                  Base HP + CON mod
                </div>
                <div className='text-2xl font-display'>
                  {draft.class ? getClassBaseHP(draft.class) : '-'} +
                  {getAttributeModifier(draft.attributes.CON)} =
                  <b>{derivedPreview?.maxHp ?? '-'}</b>
                </div>
              </CardContent>
            </Card>
            <Card variant='parchment'>
              <CardContent className='p-4 pt-4'>
                <div className='text-sm text-muted-foreground'>
                  Base Load + STR mod
                </div>
                <div className='text-2xl font-display'>
                  {draft.class ? getClassBaseLoad(draft.class) : '-'} +
                  {getAttributeModifier(draft.attributes.STR)} =
                  <b>{derivedPreview?.maxLoad ?? '-'}</b>
                </div>
              </CardContent>
            </Card>
            <Card variant='parchment'>
              <CardContent className='p-4 pt-4'>
                <div className='text-sm text-muted-foreground'>Damage Die</div>
                <div className='text-2xl font-display'>
                  {draft.class ? getClassDamageDie(draft.class) : '-'}
                </div>
              </CardContent>
            </Card>
          </div>
        )}

        {step === 'bonds' && (
          <div className='space-y-4'>
            <div className='text-sm text-muted-foreground'>
              Choose or write bonds. They can be updated later.
            </div>
            <div className='grid md:grid-cols-2 gap-3'>
              {(draft.class ? CLASS_BOND_TEMPLATES[draft.class] : []).map(
                (template) => (
                  <Button
                    key={template}
                    variant='outline'
                    onClick={() =>
                      setDraft((d) => {
                        const existingBonds = d.bonds || []
                        if (
                          existingBonds.some((bond) => bond.text === template)
                        ) {
                          return d
                        }
                        return {
                          ...d,
                          bonds: [...existingBonds, createBondDraft(template)],
                        }
                      })
                    }
                  >
                    + {template}
                  </Button>
                ),
              )}
            </div>
            <div className='grid gap-2'>
              {(draft.bonds || []).map((bond) => (
                <div key={bond.id} className='flex items-center gap-2'>
                  <Input
                    value={bond.text}
                    onChange={(e) => {
                      const nextValue = e.target.value
                      setDraft((d) => ({
                        ...d,
                        bonds: (d.bonds || []).map((existing) =>
                          existing.id === bond.id
                            ? { ...existing, text: nextValue }
                            : existing,
                        ),
                      }))
                    }}
                  />
                  <Button
                    variant='secondary'
                    onClick={() =>
                      setDraft((d) => ({
                        ...d,
                        bonds: (d.bonds || []).filter(
                          (existing) => existing.id !== bond.id,
                        ),
                      }))
                    }
                  >
                    Remove
                  </Button>
                </div>
              ))}
              <Button
                variant='outline'
                onClick={() =>
                  setDraft((d) => ({
                    ...d,
                    bonds: [...(d.bonds || []), createBondDraft('')],
                  }))
                }
              >
                + Custom Bond
              </Button>
            </div>
          </div>
        )}

        {step === 'gear' && (
          <div className='space-y-4'>
            {draft.class ? (
              <>
                <div className='text-sm text-muted-foreground'>
                  Starting gear ({draft.class})
                </div>
                <ul className='list-disc pl-5 text-sm'>
                  {CLASS_STARTING_GEAR[draft.class].base.map((item) => (
                    <li key={`${slugify(item.name)}-${item.category}`}>
                      {item.name}
                    </li>
                  ))}
                </ul>
                {CLASS_STARTING_GEAR[draft.class].choice && (
                  <div className='mt-3'>
                    <p className='text-sm font-medium'>
                      {CLASS_STARTING_GEAR[draft.class].choice!.prompt}
                    </p>
                    <div className='grid md:grid-cols-2 gap-3 mt-2'>
                      {CLASS_STARTING_GEAR[draft.class].choice!.options.map(
                        (opt, optionIndex) => {
                          const optionKeySource = opt
                            .map((item) => `${item.name}-${item.category}`)
                            .join('-')
                          const optionKey =
                            slugify(optionKeySource) || optionKeySource
                          const optionLabel = opt
                            .map((item) => item.name)
                            .join(', ')
                          return (
                            <Button
                              key={optionKey}
                              variant={
                                draft.gearChoiceIndex === optionIndex
                                  ? 'primary'
                                  : 'outline'
                              }
                              onClick={() =>
                                setDraft((d) => ({
                                  ...d,
                                  gearChoiceIndex: optionIndex,
                                }))
                              }
                            >
                              {optionLabel}
                            </Button>
                          )
                        },
                      )}
                    </div>
                  </div>
                )}
              </>
            ) : (
              <div className='text-sm'>
                Select a class to see starting equipment.
              </div>
            )}
          </div>
        )}

        {step === 'spellcasting' && (
          <div className='space-y-4'>
            {!isSpellcaster(draft.class) && !requiresDeity(draft.class) ? (
              <div className='text-center text-sm text-muted-foreground'>
                {draft.class} does not require spellcasting setup.
              </div>
            ) : (
              <div className='space-y-6'>
                {/* Deity Selection for Clerics/Paladins */}
                {requiresDeity(draft.class) && (
                  <div>
                    <h3 className='text-lg font-semibold mb-3'>
                      Choose Your Deity
                    </h3>
                    <div className='text-sm text-muted-foreground mb-4'>
                      As a {draft.class}, your divine magic comes from your
                      devotion to a deity.
                    </div>
                    <div className='grid grid-cols-1 md:grid-cols-2 gap-3'>
                      {DUNGEON_WORLD_DEITIES.map((deity) => (
                        <Button
                          key={deity.name}
                          variant={
                            draft.deity === deity.name ? 'primary' : 'outline'
                          }
                          onClick={() =>
                            setDraft((d) => ({ ...d, deity: deity.name }))
                          }
                          className='flex flex-col items-start p-4 h-auto'
                        >
                          <div className='font-medium'>{deity.name}</div>
                          <div className='text-xs opacity-75'>
                            Domain:
                            {deity.domain}
                          </div>
                          <div className='text-xs opacity-75'>
                            Alignment:
                            {deity.alignment}
                          </div>
                        </Button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Spell Preparation for Clerics */}
                {draft.class === 'Cleric' && (
                  <div>
                    <h3 className='text-lg font-semibold mb-3'>
                      Choose Your Prayers
                    </h3>
                    <div className='text-sm text-muted-foreground mb-4'>
                      Select up to 2 first-level spells to prepare for your
                      adventuring day.
                    </div>
                    <div className='grid grid-cols-1 gap-3'>
                      {dwClericSpells
                        .filter((spell) => spell.level === 1)
                        .map((spell) => {
                          const isSelected =
                            draft.spellbook?.includes(spell.id) || false
                          const canSelect =
                            isSelected || (draft.spellbook?.length || 0) < 2
                          return (
                            <Button
                              key={spell.id}
                              variant={isSelected ? 'primary' : 'outline'}
                              disabled={!canSelect}
                              onClick={() => {
                                setDraft((d) => {
                                  const currentSpells = d.spellbook || []
                                  if (isSelected) {
                                    return {
                                      ...d,
                                      spellbook: currentSpells.filter(
                                        (id) => id !== spell.id,
                                      ),
                                    }
                                  }
                                  return {
                                    ...d,
                                    spellbook: [...currentSpells, spell.id],
                                  }
                                })
                              }}
                              className='flex flex-col items-start p-4 h-auto text-left'
                            >
                              <div className='flex items-center gap-2 w-full'>
                                <div className='font-medium'>{spell.name}</div>
                                <Badge variant='secondary' className='ml-auto'>
                                  Level
                                  {spell.level}
                                </Badge>
                              </div>
                              <div className='text-xs opacity-75 mt-1'>
                                {spell.description}
                              </div>
                              <div className='text-xs opacity-50 mt-1'>
                                Range:
                                {spell.range}
                              </div>
                            </Button>
                          )
                        })}
                    </div>
                    {draft.spellbook && (
                      <div className='text-sm text-muted-foreground mt-3'>
                        Prepared: {draft.spellbook.length}
                        /2 spells
                      </div>
                    )}
                  </div>
                )}

                {/* Spellbook Selection for Wizards */}
                {draft.class === 'Wizard' && (
                  <div>
                    <h3 className='text-lg font-semibold mb-3'>
                      Choose Starting Spells
                    </h3>
                    <div className='text-sm text-muted-foreground mb-4'>
                      Select 3 first-level spells for your starting spellbook.
                      You can learn more during play.
                    </div>
                    <div className='grid grid-cols-1 gap-3'>
                      {dwWizardSpells
                        .filter((spell) => spell.level === 1)
                        .map((spell) => {
                          const isSelected =
                            draft.spellbook?.includes(spell.id) || false
                          const canSelect =
                            isSelected || (draft.spellbook?.length || 0) < 3
                          return (
                            <Button
                              key={spell.id}
                              variant={isSelected ? 'primary' : 'outline'}
                              disabled={!canSelect}
                              onClick={() => {
                                setDraft((d) => {
                                  const currentSpells = d.spellbook || []
                                  if (isSelected) {
                                    return {
                                      ...d,
                                      spellbook: currentSpells.filter(
                                        (id) => id !== spell.id,
                                      ),
                                    }
                                  }
                                  return {
                                    ...d,
                                    spellbook: [...currentSpells, spell.id],
                                  }
                                })
                              }}
                              className='flex flex-col items-start p-4 h-auto text-left'
                            >
                              <div className='flex items-center gap-2 w-full'>
                                <div className='font-medium'>{spell.name}</div>
                                <Badge variant='secondary' className='ml-auto'>
                                  Level
                                  {spell.level}
                                </Badge>
                              </div>
                              <div className='text-xs opacity-75 mt-1'>
                                {spell.description}
                              </div>
                              <div className='text-xs opacity-50 mt-1'>
                                Range:
                                {spell.range}
                              </div>
                            </Button>
                          )
                        })}
                    </div>
                    {draft.spellbook && (
                      <div className='text-sm text-muted-foreground mt-3'>
                        Selected: {draft.spellbook.length}
                        /3 spells
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {step === 'review' && (
          <div className='space-y-3'>
            <div className='text-sm'>
              Review your character and click Create.
            </div>
            <ul className='text-sm space-y-1'>
              <li>
                <b>Name</b>: {draft.name || '-'}
              </li>
              <li>
                <b>Class</b>: {draft.class || '-'}
              </li>
              <li>
                <b>Race</b>: {draft.race || '-'}
              </li>
              <li>
                <b>Alignment</b>: {draft.alignment || '-'}
              </li>
              <li>
                <b>Attributes</b>: STR {draft.attributes.STR}, DEX{' '}
                {draft.attributes.DEX}, CON {draft.attributes.CON}, INT{' '}
                {draft.attributes.INT}, WIS {draft.attributes.WIS}, CHA{' '}
                {draft.attributes.CHA}
              </li>
              <li>
                <b>HP</b>: {derivedPreview?.maxHp ?? '-'}, <b>Load</b>:{' '}
                {derivedPreview?.maxLoad ?? '-'}, <b>Damage</b>:{' '}
                {draft.class ? getClassDamageDie(draft.class) : '-'}
              </li>
              <li>
                <b>Bonds</b>: {(draft.bonds || []).length}
              </li>
              <li>
                <b>Starting Moves</b>:{' '}
                {draft.class ? STARTING_MOVES[draft.class].join(', ') : '-'}
              </li>
              {draft.deity && (
                <li>
                  <b>Deity</b>: {draft.deity}
                </li>
              )}
              {draft.spellbook && draft.spellbook.length > 0 && (
                <li>
                  <b>Starting Spells</b>: {draft.spellbook.length}
                </li>
              )}
            </ul>
          </div>
        )}
      </CardContent>

      <div className='flex items-center justify-between px-6 pb-6'>
        <div className='flex gap-2'>
          <Button variant='outline' onClick={saveAndExit}>
            Save Draft
          </Button>
          <Button
            variant='secondary'
            onClick={() => {
              if (typeof window !== 'undefined') {
                window.localStorage.removeItem(STORAGE_KEY)
              }
              setDraft(createEmptyDraft())
            }}
          >
            Reset
          </Button>
        </div>
        <div className='flex gap-2'>
          <Button variant='ghost' onClick={back} disabled={stepIndex === 0}>
            Back
          </Button>
          {step !== 'review' ? (
            <Button variant='primary' onClick={next} disabled={!canNext}>
              Next
            </Button>
          ) : (
            <Button
              variant='primary'
              onClick={finalize}
              disabled={
                !draft.class || !draft.race || !draft.alignment || !draft.name
              }
            >
              Create Character
            </Button>
          )}
        </div>
      </div>
    </Card>
  )
}

export default CharacterBuilder

import { Switch } from '@radix-ui/react-switch'
import { motion } from 'framer-motion'
import {
  AlertTriangle,
  CheckCircle,
  Eye,
  EyeOff,
  Keyboard,
  MousePointer,
  Palette,
  Volume2,
  XCircle,
} from 'lucide-react'
import React from 'react'
import { Badge } from './Badge'
import { Button } from './Button'
import { Card, CardContent } from './Card'

interface AccessibilityIssue {
  type: 'error' | 'warning' | 'info'
  category:
    | 'keyboard'
    | 'screen-reader'
    | 'color-contrast'
    | 'focus'
    | 'semantic'
  message: string
  element?: string
  suggestion: string
}

interface AccessibilityReport {
  score: number
  issues: AccessibilityIssue[]
  passedChecks: string[]
  timestamp: Date
}

export const AccessibilityChecker: React.FC = () => {
  const [isChecking, setIsChecking] = React.useState(false)
  const [report, setReport] = React.useState<AccessibilityReport | null>(null)
  const [showDetails, setShowDetails] = React.useState(false)
  const [settings, setSettings] = React.useState({
    reduceMotion: false,
    highContrast: false,
    largeText: false,
    keyboardNavigation: true,
    screenReaderMode: false,
  })

  const runAccessibilityCheck = async () => {
    setIsChecking(true)

    // Simulate accessibility checking
    await new Promise((resolve) => setTimeout(resolve, 2000))

    const issues: AccessibilityIssue[] = []
    const passedChecks: string[] = []

    // Check keyboard navigation
    const focusableElements = document.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
    )

    if (focusableElements.length > 0) {
      passedChecks.push('Focusable elements present')
    }

    // Check for missing alt text
    const images = document.querySelectorAll('img')
    let missingAltCount = 0
    images.forEach((img) => {
      if (!img.alt && !img.getAttribute('aria-label')) {
        missingAltCount++
      }
    })

    if (missingAltCount > 0) {
      issues.push({
        type: 'error',
        category: 'screen-reader',
        message: `${missingAltCount} images missing alt text`,
        suggestion: 'Add descriptive alt text to all images',
      })
    } else if (images.length > 0) {
      passedChecks.push('All images have alt text')
    }

    // Check heading hierarchy
    const headings = Array.from(
      document.querySelectorAll('h1, h2, h3, h4, h5, h6'),
    )
    let headingIssues = 0
    let lastLevel = 0

    headings.forEach((heading) => {
      const level = Number.parseInt(heading.tagName.charAt(1))
      if (level > lastLevel + 1) {
        headingIssues++
      }
      lastLevel = level
    })

    if (headingIssues > 0) {
      issues.push({
        type: 'warning',
        category: 'semantic',
        message: 'Heading hierarchy issues detected',
        suggestion:
          'Ensure headings follow proper hierarchy (h1 ΓåÆ h2 ΓåÆ h3, etc.)',
      })
    } else if (headings.length > 0) {
      passedChecks.push('Proper heading hierarchy')
    }

    // Check form labels
    const inputs = document.querySelectorAll('input, select, textarea')
    let unlabeledInputs = 0

    inputs.forEach((input) => {
      const hasLabel =
        input.getAttribute('aria-label') ||
        input.getAttribute('aria-labelledby') ||
        document.querySelector(`label[for="${input.id}"]`)

      if (!hasLabel) {
        unlabeledInputs++
      }
    })

    if (unlabeledInputs > 0) {
      issues.push({
        type: 'error',
        category: 'screen-reader',
        message: `${unlabeledInputs} form elements missing labels`,
        suggestion: 'Add labels or aria-label attributes to all form elements',
      })
    } else if (inputs.length > 0) {
      passedChecks.push('All form elements have labels')
    }

    // Check color contrast (simplified)
    const buttons = document.querySelectorAll('button')
    let contrastIssues = 0

    buttons.forEach((button) => {
      const styles = window.getComputedStyle(button)
      const bgColor = styles.backgroundColor
      const textColor = styles.color

      // Simplified contrast check (in real implementation, use proper contrast calculation)
      if (bgColor === textColor) {
        contrastIssues++
      }
    })

    if (contrastIssues > 0) {
      issues.push({
        type: 'warning',
        category: 'color-contrast',
        message: 'Potential color contrast issues',
        suggestion:
          'Ensure text has sufficient contrast ratio (4.5:1 for normal text, 3:1 for large text)',
      })
    } else {
      passedChecks.push('Good color contrast detected')
    }

    // Check for focus indicators
    const focusableCount = focusableElements.length
    if (focusableCount > 0) {
      passedChecks.push(`${focusableCount} focusable elements found`)
    }

    // Calculate score
    const totalChecks = issues.length + passedChecks.length
    const score =
      totalChecks > 0
        ? Math.round((passedChecks.length / totalChecks) * 100)
        : 100

    setReport({
      score,
      issues,
      passedChecks,
      timestamp: new Date(),
    })

    setIsChecking(false)
  }

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-chart-2'
    if (score >= 60) return 'text-chart-4'
    return 'text-destructive'
  }

  const getScoreIcon = (score: number) => {
    if (score >= 80) return <CheckCircle className='w-5 h-5 text-chart-2' />
    if (score >= 60) return <AlertTriangle className='w-5 h-5 text-chart-4' />
    return <XCircle className='w-5 h-5 text-destructive' />
  }

  const getIssueIcon = (type: AccessibilityIssue['type']) => {
    switch (type) {
      case 'error':
        return <XCircle className='w-4 h-4 text-destructive' />
      case 'warning':
        return <AlertTriangle className='w-4 h-4 text-chart-4' />
      case 'info':
        return <CheckCircle className='w-4 h-4 text-primary' />
    }
  }

  const getCategoryIcon = (category: AccessibilityIssue['category']) => {
    switch (category) {
      case 'keyboard':
        return <Keyboard className='w-4 h-4' />
      case 'screen-reader':
        return <Volume2 className='w-4 h-4' />
      case 'color-contrast':
        return <Palette className='w-4 h-4' />
      case 'focus':
        return <MousePointer className='w-4 h-4' />
      case 'semantic':
        return <Eye className='w-4 h-4' />
    }
  }

  return (
    <Card variant='magical'>
      <CardContent className='p-6'>
        <div className='space-y-6'>
          {/* Header */}
          <div className='flex items-center justify-between'>
            <div className='flex items-center gap-3'>
              <div className='w-10 h-10 rounded-lg bg-accent/15 flex items-center justify-center'>
                <Eye className='w-5 h-5 text-accent' />
              </div>
              <div>
                <h3 className='text-lg font-display text-foreground'>
                  Accessibility Checker
                </h3>
                <p className='text-sm text-muted-foreground'>
                  Ensure ZimboMate is accessible to all users
                </p>
              </div>
            </div>

            <Button
              variant='primary'
              onClick={runAccessibilityCheck}
              disabled={isChecking}
              className='gap-2'
            >
              {isChecking ? 'Checking...' : 'Run Check'}
            </Button>
          </div>

          {/* Accessibility Settings */}
          <div className='rounded-lg p-4 bg-popover'>
            <h4 className='font-medium mb-3 text-foreground'>
              Accessibility Settings
            </h4>
            <div className='grid grid-cols-1 md:grid-cols-2 gap-4'>
              <div className='flex items-center justify-between'>
                <div className='flex items-center gap-2'>
                  <EyeOff className='w-4 h-4 text-muted-foreground' />
                  <span className='text-sm text-foreground'>Reduce Motion</span>
                </div>
                <Switch
                  checked={settings.reduceMotion}
                  onCheckedChange={(checked) =>
                    setSettings((prev) => ({ ...prev, reduceMotion: checked }))
                  }
                />
              </div>

              <div className='flex items-center justify-between'>
                <div className='flex items-center gap-2'>
                  <Palette className='w-4 h-4 text-muted-foreground' />
                  <span className='text-sm text-foreground'>High Contrast</span>
                </div>
                <Switch
                  checked={settings.highContrast}
                  onCheckedChange={(checked) =>
                    setSettings((prev) => ({ ...prev, highContrast: checked }))
                  }
                />
              </div>

              <div className='flex items-center justify-between'>
                <div className='flex items-center gap-2'>
                  <Eye className='w-4 h-4 text-muted-foreground' />
                  <span className='text-sm text-foreground'>Large Text</span>
                </div>
                <Switch
                  checked={settings.largeText}
                  onCheckedChange={(checked) =>
                    setSettings((prev) => ({ ...prev, largeText: checked }))
                  }
                />
              </div>

              <div className='flex items-center justify-between'>
                <div className='flex items-center gap-2'>
                  <Keyboard className='w-4 h-4 text-muted-foreground' />
                  <span className='text-sm text-foreground'>
                    Keyboard Navigation
                  </span>
                </div>
                <Switch
                  checked={settings.keyboardNavigation}
                  onCheckedChange={(checked) =>
                    setSettings((prev) => ({
                      ...prev,
                      keyboardNavigation: checked,
                    }))
                  }
                />
              </div>
            </div>
          </div>

          {/* Results */}
          {report && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className='space-y-4'
            >
              {/* Score */}
              <div
                className='border rounded-lg p-4'
                style={{
                  backgroundColor: 'var(--card)',
                  borderColor: 'var(--border)',
                }}
              >
                <div className='flex items-center justify-between mb-4'>
                  <div className='flex items-center gap-3'>
                    {getScoreIcon(report.score)}
                    <div>
                      <div
                        className={`text-2xl font-bold ${getScoreColor(report.score)}`}
                      >
                        {report.score}%
                      </div>
                      <div className='text-sm text-muted-foreground'>
                        Accessibility Score
                      </div>
                    </div>
                  </div>

                  <div className='text-right'>
                    <div className='text-sm text-muted-foreground'>
                      {report.passedChecks.length} passed
                    </div>
                    <div className='text-sm text-muted-foreground'>
                      {report.issues.length} issues
                    </div>
                  </div>
                </div>

                <div className='text-xs text-muted-foreground'>
                  Last checked: {report.timestamp.toLocaleString()}
                </div>
              </div>

              {/* Issues */}
              {report.issues.length > 0 && (
                <div className='space-y-2'>
                  <h4 className='font-medium text-foreground'>Issues Found</h4>
                  {report.issues.map((issue, index) => (
                    <div
                      key={index}
                      className='border rounded-lg p-3'
                      style={{
                        backgroundColor: 'var(--card)',
                        borderColor: 'var(--border)',
                      }}
                    >
                      <div className='flex items-start gap-3'>
                        <div className='flex items-center gap-2 mt-0.5'>
                          {getIssueIcon(issue.type)}
                          {getCategoryIcon(issue.category)}
                        </div>
                        <div className='flex-1'>
                          <div className='font-medium text-sm text-foreground'>
                            {issue.message}
                          </div>
                          <div className='text-xs mt-1 text-muted-foreground'>
                            {issue.suggestion}
                          </div>
                          {issue.element && (
                            <Badge variant='secondary' className='text-xs mt-2'>
                              {issue.element}
                            </Badge>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* Passed Checks */}
              <div className='flex justify-center'>
                <Button
                  variant='ghost'
                  size='sm'
                  onClick={() => setShowDetails(!showDetails)}
                >
                  {showDetails ? 'Hide' : 'Show'} Passed Checks
                </Button>
              </div>

              {showDetails && report.passedChecks.length > 0 && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  exit={{ opacity: 0, height: 0 }}
                >
                  <h4 className='font-medium mb-2 text-foreground'>
                    Passed Checks
                  </h4>
                  <div className='space-y-1'>
                    {report.passedChecks.map((check, index) => (
                      <div
                        key={index}
                        className='flex items-center gap-2 text-sm text-chart-2'
                      >
                        <CheckCircle className='w-3 h-3' />
                        {check}
                      </div>
                    ))}
                  </div>
                </motion.div>
              )}
            </motion.div>
          )}

          {/* Guidelines */}
          <div
            className='border rounded-lg p-4'
            style={{
              backgroundColor: 'var(--popover)',
              borderColor: 'var(--border)',
            }}
          >
            <h4 className='font-medium mb-2 text-foreground'>
              Accessibility Guidelines
            </h4>
            <ul className='space-y-1 text-sm text-muted-foreground'>
              <li>ΓÇó Ensure all interactive elements are keyboard accessible</li>
              <li>ΓÇó Provide alternative text for images and icons</li>
              <li>ΓÇó Use proper heading hierarchy (h1 ΓåÆ h2 ΓåÆ h3)</li>
              <li>ΓÇó Maintain sufficient color contrast ratios</li>
              <li>ΓÇó Label all form elements clearly</li>
              <li>ΓÇó Provide focus indicators for all interactive elements</li>
              <li>ΓÇó Support screen readers with proper ARIA attributes</li>
            </ul>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

export default AccessibilityChecker

import React, { createContext, useCallback, useEffect, useState } from 'react'

export interface User {
  id: string
  name: string
  email?: string
  avatar?: string
  preferences: {
    theme: string
    language: string
    timezone: string
  }
  createdAt: Date
  lastActive: Date
}

interface AuthContextType {
  user: User | null
  isAuthenticated: boolean
  login: (credentials: { name: string; email?: string }) => Promise<void>
  logout: () => void
  updateUser: (updates: Partial<User>) => void
  isLoading: boolean
}

const AuthContext = createContext<AuthContextType | null>(null)

interface AuthProviderProps {
  children: React.ReactNode
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  // Initialize user from localStorage on mount
  useEffect(() => {
    const initializeAuth = () => {
      try {
        const storedUser = localStorage.getItem('zimbomate-user')
        if (storedUser) {
          const userData = JSON.parse(storedUser)
          setUser({
            ...userData,
            createdAt: new Date(userData.createdAt),
            lastActive: new Date(userData.lastActive),
          })
        }
      } catch (error) {
        console.warn('Failed to load user data from localStorage:', error)
        localStorage.removeItem('zimbomate-user')
      } finally {
        setIsLoading(false)
      }
    }

    initializeAuth()
  }, [])

  // Update lastActive timestamp periodically
  useEffect(() => {
    if (user) {
      const interval = setInterval(() => {
        setUser((prev) => (prev ? { ...prev, lastActive: new Date() } : null))
      }, 60000) // Update every minute

      return () => clearInterval(interval)
    }
  }, [user])

  // Persist user data to localStorage whenever it changes
  useEffect(() => {
    if (user) {
      localStorage.setItem('zimbomate-user', JSON.stringify(user))
    } else {
      localStorage.removeItem('zimbomate-user')
    }
  }, [user])

  const login = useCallback(
    async (credentials: { name: string; email?: string }) => {
      setIsLoading(true)

      // Simulate API call delay
      await new Promise((resolve) => setTimeout(resolve, 500))

      const newUser: User = {
        id: `user-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        name: credentials.name,
        email: credentials.email,
        preferences: {
          theme: 'fantasy',
          language: 'en',
          timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        },
        createdAt: new Date(),
        lastActive: new Date(),
      }

      setUser(newUser)
      setIsLoading(false)
    },
    [],
  )

  const logout = useCallback(() => {
    setUser(null)
    localStorage.removeItem('zimbomate-user')
    // Clear other user-specific data
    localStorage.removeItem('zimbomate-characters')
    localStorage.removeItem('zimbomate-campaigns')
    localStorage.removeItem('zimbomate-preferences')
  }, [])

  const updateUser = useCallback((updates: Partial<User>) => {
    setUser((prev) =>
      prev ? { ...prev, ...updates, lastActive: new Date() } : null,
    )
  }, [])

  const value: AuthContextType = {
    user,
    isAuthenticated: !!user,
    login,
    logout,
    updateUser,
    isLoading,
  }

  return <AuthContext value={value}>{children}</AuthContext>
}

export function useAuth(): AuthContextType {
  const context = use(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

// Helper function to get current user ID for services
export function getCurrentUserId(): string | null {
  try {
    const storedUser = localStorage.getItem('zimbomate-user')
    if (storedUser) {
      const userData = JSON.parse(storedUser)
      return userData.id
    }
  } catch (error) {
    console.warn('Failed to get current user ID:', error)
  }
  return null
}

// Guest user creation for offline usage
export function createGuestUser(): User {
  return {
    id: `guest-${Date.now()}`,
    name: 'Guest Player',
    preferences: {
      theme: 'fantasy',
      language: 'en',
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    },
    createdAt: new Date(),
    lastActive: new Date(),
  }
}

