/**
 * useAnimations Hook for ZimboMate V2
 * Animation control and preferences with magical particle effects
 * Provides staggered animations, particle systems, and performance optimization
 */

import { useCallback, useEffect, useRef, useState } from 'react'

export interface AnimationPreferences {
  reduceMotion: boolean
  particleEffects: boolean
  staggeredAnimations: boolean
  glowEffects: boolean
  transitionSpeed: 'slow' | 'normal' | 'fast'
}

export interface ParticleConfig {
  count: number
  colors: string[]
  size: { min: number; max: number }
  speed: { min: number; max: number }
  lifetime: number
  gravity: number
  spread: number
}

export interface StaggerConfig {
  delay: number
  duration: number
  easing: string
  direction: 'up' | 'down' | 'left' | 'right' | 'center'
}

export interface UseAnimationsReturn {
  // Animation preferences
  preferences: AnimationPreferences
  updatePreferences: (updates: Partial<AnimationPreferences>) => void

  // Particle effects
  triggerParticles: (
    element: HTMLElement | null,
    type: 'success' | 'failure' | 'damage' | 'healing' | 'magic' | 'custom',
    config?: Partial<ParticleConfig>,
  ) => void
  createParticleSystem: (
    container: HTMLElement,
    config: ParticleConfig,
  ) => () => void // Returns cleanup function

  // Staggered animations
  useStaggeredAnimation: (
    elements: HTMLElement[],
    config?: Partial<StaggerConfig>,
  ) => void
  createStaggeredEntrance: (
    selector: string,
    config?: Partial<StaggerConfig>,
  ) => void

  // Magical effects
  addMagicalGlow: (
    element: HTMLElement | null,
    color?: string,
    intensity?: number,
  ) => void
  removeMagicalGlow: (element: HTMLElement | null) => void
  pulseElement: (element: HTMLElement | null, duration?: number) => void
  shimmerEffect: (element: HTMLElement | null, duration?: number) => void

  // Animation utilities
  getAnimationDuration: (baseMs: number) => number
  shouldAnimate: (
    animationType: 'particle' | 'stagger' | 'glow' | 'transition',
  ) => boolean
  createSpringConfig: (type: 'gentle' | 'wobbly' | 'stiff' | 'slow') => any

  // Performance
  isHighPerformance: boolean
  togglePerformanceMode: () => void

  // Theme integration
  getThemeColors: () => {
    primary: string
    secondary: string
    accent: string
    success: string
    warning: string
    error: string
  }
}

/**
 * Hook for managing animations and visual effects
 */
export function useAnimations(): UseAnimationsReturn {
  const [preferences, setPreferences] = useState<AnimationPreferences>(() => {
    // Check for user's motion preferences
    const prefersReducedMotion = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches

    return {
      reduceMotion: prefersReducedMotion,
      particleEffects: !prefersReducedMotion,
      staggeredAnimations: !prefersReducedMotion,
      glowEffects: true,
      transitionSpeed: 'normal',
    }
  })

  const [isHighPerformance, setIsHighPerformance] = useState(true)
  const particleSystemsRef = useRef<Map<string, () => void>>(new Map())

  // Monitor performance
  useEffect(() => {
    const checkPerformance = () => {
      // Simple performance check based on frame rate
      const start = performance.now()
      requestAnimationFrame(() => {
        const delta = performance.now() - start
        setIsHighPerformance(delta < 16.67) // 60fps threshold
      })
    }

    const interval = setInterval(checkPerformance, 5000)
    return () => clearInterval(interval)
  }, [])

  // Update preferences
  const updatePreferences = useCallback(
    (updates: Partial<AnimationPreferences>) => {
      setPreferences((prev) => ({ ...prev, ...updates }))
    },
    [],
  )

  // Get theme colors
  const getThemeColors = useCallback(() => {
    return {
      primary: 'var(--matsu-primary, var(--primary))',
      secondary: 'var(--matsu-secondary, var(--secondary))',
      accent: 'var(--matsu-accent, var(--accent))',
      success: 'var(--chart-2)',
      warning: 'var(--chart-4)',
      error: 'var(--destructive)',
    }
  }, [])

  // Particle effects
  const triggerParticles = useCallback(
    (
      element: HTMLElement | null,
      type: 'success' | 'failure' | 'damage' | 'healing' | 'magic' | 'custom',
      config: Partial<ParticleConfig> = {},
    ) => {
      if (!element || !preferences.particleEffects || preferences.reduceMotion)
        return

      const themeColors = getThemeColors()
      const defaultConfigs: Record<string, ParticleConfig> = {
        success: {
          count: 20,
          colors: [themeColors.success, '#10B981', '#34D399'],
          size: { min: 2, max: 6 },
          speed: { min: 50, max: 150 },
          lifetime: 1000,
          gravity: 0.5,
          spread: 45,
        },
        failure: {
          count: 15,
          colors: [themeColors.error, '#EF4444', '#F87171'],
          size: { min: 1, max: 4 },
          speed: { min: 30, max: 100 },
          lifetime: 800,
          gravity: 0.8,
          spread: 30,
        },
        damage: {
          count: 25,
          colors: ['#DC2626', '#B91C1C', '#991B1B'],
          size: { min: 3, max: 8 },
          speed: { min: 100, max: 200 },
          lifetime: 600,
          gravity: 1.2,
          spread: 60,
        },
        healing: {
          count: 30,
          colors: ['#10B981', '#34D399', '#6EE7B7'],
          size: { min: 2, max: 5 },
          speed: { min: 20, max: 80 },
          lifetime: 1500,
          gravity: -0.3, // Float upward
          spread: 90,
        },
        magic: {
          count: 40,
          colors: [
            themeColors.primary,
            themeColors.accent,
            '#8B5CF6',
            '#A78BFA',
          ],
          size: { min: 1, max: 7 },
          speed: { min: 40, max: 120 },
          lifetime: 2000,
          gravity: 0.1,
          spread: 120,
        },
        custom: {
          count: 20,
          colors: [themeColors.primary],
          size: { min: 2, max: 5 },
          speed: { min: 50, max: 100 },
          lifetime: 1000,
          gravity: 0.5,
          spread: 45,
        },
      }

      const finalConfig = { ...defaultConfigs[type], ...config }

      // Create particle system
      const rect = element.getBoundingClientRect()
      const container = document.createElement('div')
      container.style.position = 'fixed'
      container.style.top = '0'
      container.style.left = '0'
      container.style.width = '100vw'
      container.style.height = '100vh'
      container.style.pointerEvents = 'none'
      container.style.zIndex = '9999'

      document.body.appendChild(container)

      // Generate particles
      for (let i = 0; i < finalConfig.count; i++) {
        const particle = document.createElement('div')
        const size =
          Math.random() * (finalConfig.size.max - finalConfig.size.min) +
          finalConfig.size.min
        const color =
          finalConfig.colors[
            Math.floor(Math.random() * finalConfig.colors.length)
          ]
        const angle =
          (Math.random() - 0.5) * finalConfig.spread * (Math.PI / 180)
        const speed =
          Math.random() * (finalConfig.speed.max - finalConfig.speed.min) +
          finalConfig.speed.min

        particle.style.position = 'absolute'
        particle.style.width = `${size}px`
        particle.style.height = `${size}px`
        particle.style.backgroundColor = color
        particle.style.borderRadius = '50%'
        particle.style.left = `${rect.left + rect.width / 2}px`
        particle.style.top = `${rect.top + rect.height / 2}px`
        particle.style.boxShadow = `0 0 ${size * 2}px ${color}`

        container.appendChild(particle)

        // Animate particle
        const startTime = performance.now()
        const animate = (currentTime: number) => {
          const elapsed = currentTime - startTime
          const progress = elapsed / finalConfig.lifetime

          if (progress >= 1) {
            particle.remove()
            return
          }

          const x = Math.cos(angle) * speed * (elapsed / 1000)
          const y =
            Math.sin(angle) * speed * (elapsed / 1000) +
            finalConfig.gravity * (elapsed / 1000) ** 2 * 100
          const opacity = 1 - progress

          particle.style.transform = `translate(${x}px, ${y}px)`
          particle.style.opacity = opacity.toString()

          requestAnimationFrame(animate)
        }

        requestAnimationFrame(animate)
      }

      // Cleanup container after all particles are done
      setTimeout(() => {
        if (container.parentNode) {
          container.remove()
        }
      }, finalConfig.lifetime + 100)
    },
    [preferences, getThemeColors],
  )

  // Create persistent particle system
  const createParticleSystem = useCallback(
    (container: HTMLElement, config: ParticleConfig) => {
      if (!preferences.particleEffects || preferences.reduceMotion) {
        return () => {} // Return empty cleanup function
      }

      const systemId = Math.random().toString(36).slice(2, 11)
      let isActive = true

      const generateParticle = () => {
        if (!isActive) return

        const particle = document.createElement('div')
        const size =
          Math.random() * (config.size.max - config.size.min) + config.size.min
        const color =
          config.colors[Math.floor(Math.random() * config.colors.length)]

        particle.style.position = 'absolute'
        particle.style.width = `${size}px`
        particle.style.height = `${size}px`
        particle.style.backgroundColor = color
        particle.style.borderRadius = '50%'
        particle.style.pointerEvents = 'none'

        container.appendChild(particle)

        // Animate and remove particle
        setTimeout(() => {
          if (particle.parentNode) {
            particle.remove()
          }
        }, config.lifetime)

        // Schedule next particle
        if (isActive) {
          setTimeout(generateParticle, Math.random() * 200 + 100)
        }
      }

      // Start generating particles
      generateParticle()

      // Return cleanup function
      const cleanup = () => {
        isActive = false
        particleSystemsRef.current.delete(systemId)
      }

      particleSystemsRef.current.set(systemId, cleanup)
      return cleanup
    },
    [preferences],
  )

  // Staggered animations
  const useStaggeredAnimation = useCallback(
    (elements: HTMLElement[], config: Partial<StaggerConfig> = {}) => {
      if (!preferences.staggeredAnimations || preferences.reduceMotion) return

      const defaultConfig: StaggerConfig = {
        delay: 100,
        duration: 300,
        easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
        direction: 'up',
      }

      const finalConfig = { ...defaultConfig, ...config }

      elements.forEach((element, index) => {
        if (!element) return

        const delay = index * finalConfig.delay

        // Set initial state
        element.style.opacity = '0'
        element.style.transform = getInitialTransform(finalConfig.direction)
        element.style.transition = `opacity ${finalConfig.duration}ms ${finalConfig.easing} ${delay}ms, transform ${finalConfig.duration}ms ${finalConfig.easing} ${delay}ms`

        // Trigger animation
        requestAnimationFrame(() => {
          element.style.opacity = '1'
          element.style.transform = 'translate(0, 0) scale(1)'
        })
      })
    },
    [preferences],
  )

  const applyStaggeredAnimation = useStaggeredAnimation

  const createStaggeredEntrance = useCallback(
    (selector: string, config: Partial<StaggerConfig> = {}) => {
      const elements = Array.from(
        document.querySelectorAll(selector),
      ) as HTMLElement[]
      if (elements.length === 0) return
      applyStaggeredAnimation(elements, config)
    },
    [applyStaggeredAnimation],
  )

  // Magical effects
  const addMagicalGlow = useCallback(
    (element: HTMLElement | null, color = 'var(--primary)', intensity = 1) => {
      if (!element || !preferences.glowEffects) return

      const glowSize = 10 * intensity
      element.style.boxShadow = `0 0 ${glowSize}px ${color}, 0 0 ${glowSize * 2}px ${color}`
      element.style.transition = 'box-shadow 0.3s ease'
    },
    [preferences],
  )

  const removeMagicalGlow = useCallback((element: HTMLElement | null) => {
    if (!element) return
    element.style.boxShadow = ''
  }, [])

  const pulseElement = useCallback(
    (element: HTMLElement | null, duration = 1000) => {
      if (!element || preferences.reduceMotion) return

      element.style.animation = `pulse ${duration}ms ease-in-out`

      // Remove animation after completion
      setTimeout(() => {
        element.style.animation = ''
      }, duration)
    },
    [preferences],
  )

  const shimmerEffect = useCallback(
    (element: HTMLElement | null, duration = 2000) => {
      if (!element || preferences.reduceMotion) return

      element.style.animation = `shimmer ${duration}ms ease-in-out infinite`

      // Remove animation after specified duration
      setTimeout(() => {
        element.style.animation = ''
      }, duration)
    },
    [preferences],
  )

  // Animation utilities
  const getAnimationDuration = useCallback(
    (baseMs: number) => {
      if (preferences.reduceMotion) return 0

      const speedMultipliers = {
        slow: 1.5,
        normal: 1,
        fast: 0.7,
      }

      return baseMs * speedMultipliers[preferences.transitionSpeed]
    },
    [preferences],
  )

  const shouldAnimate = useCallback(
    (animationType: 'particle' | 'stagger' | 'glow' | 'transition') => {
      if (preferences.reduceMotion) return false
      if (
        !isHighPerformance &&
        (animationType === 'particle' || animationType === 'stagger')
      )
        return false

      switch (animationType) {
        case 'particle':
          return preferences.particleEffects
        case 'stagger':
          return preferences.staggeredAnimations
        case 'glow':
          return preferences.glowEffects
        case 'transition':
          return true
        default:
          return true
      }
    },
    [preferences, isHighPerformance],
  )

  const createSpringConfig = useCallback(
    (type: 'gentle' | 'wobbly' | 'stiff' | 'slow') => {
      const configs = {
        gentle: { tension: 120, friction: 14 },
        wobbly: { tension: 180, friction: 12 },
        stiff: { tension: 210, friction: 20 },
        slow: { tension: 280, friction: 60 },
      }

      return configs[type]
    },
    [],
  )

  const togglePerformanceMode = useCallback(() => {
    setIsHighPerformance((prev) => !prev)
  }, [])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      // Cleanup all particle systems
      const cleanupFns = Array.from(particleSystemsRef.current.values())
      particleSystemsRef.current.clear()
      cleanupFns.forEach((cleanup) => cleanup())
    }
  }, [])

  return {
    // Animation preferences
    preferences,
    updatePreferences,

    // Particle effects
    triggerParticles,
    createParticleSystem,

    // Staggered animations
    useStaggeredAnimation,
    createStaggeredEntrance,

    // Magical effects
    addMagicalGlow,
    removeMagicalGlow,
    pulseElement,
    shimmerEffect,

    // Animation utilities
    getAnimationDuration,
    shouldAnimate,
    createSpringConfig,

    // Performance
    isHighPerformance,
    togglePerformanceMode,

    // Theme integration
    getThemeColors,
  }
}

// Helper function for initial transform based on direction
function getInitialTransform(direction: StaggerConfig['direction']): string {
  switch (direction) {
    case 'up':
      return 'translateY(20px) scale(0.95)'
    case 'down':
      return 'translateY(-20px) scale(0.95)'
    case 'left':
      return 'translateX(20px) scale(0.95)'
    case 'right':
      return 'translateX(-20px) scale(0.95)'
    case 'center':
      return 'scale(0.8)'
    default:
      return 'translateY(20px) scale(0.95)'
  }
}

/**
 * useCharacter Hook for ZimboMate V2
 * Primary character management hook - foundation for all character operations
 * Integrates characterStore with CharacterStateService and AdvancementService
 */

import type { Character } from '../models/Character'
import { useCallback, useMemo } from 'react'
import { advancementService } from '../services/AdvancementService'
import { characterStateService } from '../services/CharacterStateService'
import { useCharacterStore } from '../stores/characterStore'

export interface UseCharacterReturn {
  // Character data
  character: Character | undefined
  isLoading: boolean
  error: string | null

  // Character operations
  updateCharacter: (updates: Partial<Character>) => void
  deleteCharacter: () => void
  duplicateCharacter: () => Character | undefined
  exportCharacter: () => string | undefined

  // Health management
  updateHP: (newHP: number) => void
  healCharacter: (amount: number) => void
  damageCharacter: (amount: number) => void

  // Load management
  updateLoad: (newLoad: number) => void

  // XP and advancement
  addXP: (amount: number, source: string, description: string) => void
  levelUp: () => void
  canLevelUp: boolean

  // Character state integration
  getStateSummary: () => {
    activeConditions: number
    totalOngoingModifiers: number
    availableForwardModifiers: number
    resourcesNeedingAttention: number
  }

  // Utility
  clearError: () => void
}

/**
 * Primary character management hook
 * @param characterId - Optional character ID. If not provided, uses active character
 * @returns Character data and operations
 */
export function useCharacter(characterId?: string): UseCharacterReturn {
  const {
    characters,
    activeCharacterId,
    isLoading,
    error,
    getCharacter,
    updateCharacter: storeUpdateCharacter,
    deleteCharacter: storeDeleteCharacter,
    duplicateCharacter: storeDuplicateCharacter,
    exportCharacter: storeExportCharacter,
    updateHP: storeUpdateHP,
    healCharacter: storeHealCharacter,
    damageCharacter: storeDamageCharacter,
    updateLoad: storeUpdateLoad,
    addXP: storeAddXP,
    levelUpCharacter: storeLevelUpCharacter,
    clearError,
  } = useCharacterStore()

  // Determine which character to use
  const targetCharacterId = characterId || activeCharacterId
  const character = useMemo(() => {
    if (!targetCharacterId) return undefined
    return getCharacter(targetCharacterId)
  }, [targetCharacterId, getCharacter, characters])

  // Character operations
  const updateCharacter = useCallback(
    (updates: Partial<Character>) => {
      if (!targetCharacterId) return
      storeUpdateCharacter(targetCharacterId, updates)
    },
    [targetCharacterId, storeUpdateCharacter],
  )

  const deleteCharacter = useCallback(() => {
    if (!targetCharacterId) return
    storeDeleteCharacter(targetCharacterId)
  }, [targetCharacterId, storeDeleteCharacter])

  const duplicateCharacter = useCallback(() => {
    if (!targetCharacterId) return undefined
    return storeDuplicateCharacter(targetCharacterId)
  }, [targetCharacterId, storeDuplicateCharacter])

  const exportCharacter = useCallback(() => {
    if (!targetCharacterId) return undefined
    return storeExportCharacter(targetCharacterId)
  }, [targetCharacterId, storeExportCharacter])

  // Health management
  const updateHP = useCallback(
    (newHP: number) => {
      if (!targetCharacterId) return
      storeUpdateHP(targetCharacterId, newHP)
    },
    [targetCharacterId, storeUpdateHP],
  )

  const healCharacter = useCallback(
    (amount: number) => {
      if (!targetCharacterId) return
      storeHealCharacter(targetCharacterId, amount)
    },
    [targetCharacterId, storeHealCharacter],
  )

  const damageCharacter = useCallback(
    (amount: number) => {
      if (!targetCharacterId) return
      storeDamageCharacter(targetCharacterId, amount)
    },
    [targetCharacterId, storeDamageCharacter],
  )

  // Load management
  const updateLoad = useCallback(
    (newLoad: number) => {
      if (!targetCharacterId) return
      storeUpdateLoad(targetCharacterId, newLoad)
    },
    [targetCharacterId, storeUpdateLoad],
  )

  // XP and advancement
  const addXP = useCallback(
    (amount: number, source: string, description: string) => {
      if (!targetCharacterId) return
      storeAddXP(targetCharacterId, amount, source, description)
    },
    [targetCharacterId, storeAddXP],
  )

  const levelUp = useCallback(() => {
    if (!targetCharacterId) return
    storeLevelUpCharacter(targetCharacterId)
  }, [targetCharacterId, storeLevelUpCharacter])

  const canLevelUp = useMemo(() => {
    if (!character) return false
    return advancementService.shouldLevelUp(character)
  }, [character])

  // Character state integration
  const getStateSummary = useCallback(() => {
    if (!targetCharacterId) {
      return {
        activeConditions: 0,
        totalOngoingModifiers: 0,
        availableForwardModifiers: 0,
        resourcesNeedingAttention: 0,
      }
    }
    return characterStateService.getStateSummary(targetCharacterId)
  }, [targetCharacterId])

  return {
    // Character data
    character,
    isLoading,
    error,

    // Character operations
    updateCharacter,
    deleteCharacter,
    duplicateCharacter,
    exportCharacter,

    // Health management
    updateHP,
    healCharacter,
    damageCharacter,

    // Load management
    updateLoad,

    // XP and advancement
    addXP,
    levelUp,
    canLevelUp,

    // Character state integration
    getStateSummary,

    // Utility
    clearError,
  }
}

/**
 * Hook for managing multiple characters
 * @returns All characters and bulk operations
 */
export function useCharacters() {
  const {
    characters,
    isLoading,
    error,
    createCharacter,
    importCharacter,
    clearError,
  } = useCharacterStore()

  const createNewCharacter = useCallback(
    (characterData: Omit<Character, 'id' | 'createdAt' | 'updatedAt'>) => {
      return createCharacter(characterData)
    },
    [createCharacter],
  )

  const importFromData = useCallback(
    (characterData: string) => {
      return importCharacter(characterData)
    },
    [importCharacter],
  )

  return {
    characters,
    isLoading,
    error,
    createCharacter: createNewCharacter,
    importCharacter: importFromData,
    clearError,
  }
}

/**
 * useCharacterStats Hook for ZimboMate V2
 * Manages character stats with dynamic modifiers and real-time calculations
 * Integrates base stats with conditions, equipment, and temporary modifiers
 */

import type { Attribute, Character } from '../models/Character'
import { useCallback, useMemo } from 'react'
import { characterStateService } from '../services/CharacterStateService'
import { useCharacter } from './useCharacter'

export interface StatWithModifiers {
  base: number
  modifier: number
  total: number
  breakdown: Array<{
    source: string
    value: number
    type: 'base' | 'condition' | 'equipment' | 'ongoing' | 'temporary'
  }>
}

export interface UseCharacterStatsReturn {
  // Character reference
  character: Character | undefined

  // Individual stats with modifiers
  strength: StatWithModifiers
  dexterity: StatWithModifiers
  constitution: StatWithModifiers
  intelligence: StatWithModifiers
  wisdom: StatWithModifiers
  charisma: StatWithModifiers

  // Computed values
  hitPoints: {
    current: number
    max: number
    percentage: number
  }

  load: {
    current: number
    max: number
    percentage: number
    status: 'light' | 'normal' | 'heavy' | 'overloaded'
  }

  // Stat operations
  updateBaseStat: (stat: keyof Attribute, value: number) => void
  getStatModifier: (stat: keyof Attribute) => number
  getStatTotal: (stat: keyof Attribute) => number

  // Modifier management
  getTotalModifierForStat: (stat: keyof Attribute) => number
  getModifierBreakdown: (stat: keyof Attribute) => Array<{
    source: string
    value: number
    type: string
  }>

  // Utility
  isLoading: boolean
  error: string | null
}

/**
 * Hook for managing character stats with dynamic modifiers
 * @param characterId - Character ID (optional, uses active character if not provided)
 */
export function useCharacterStats(
  characterId?: string,
): UseCharacterStatsReturn {
  const { character, updateCharacter, isLoading, error } =
    useCharacter(characterId)

  // Helper function to calculate stat with modifiers
  const calculateStatWithModifiers = useCallback(
    (statName: keyof Attribute, baseValue: number): StatWithModifiers => {
      if (!character) {
        return {
          base: baseValue,
          modifier: 0,
          total: baseValue,
          breakdown: [{ source: 'Base', value: baseValue, type: 'base' }],
        }
      }

      const breakdown: Array<{
        source: string
        value: number
        type: 'base' | 'condition' | 'equipment' | 'ongoing' | 'temporary'
      }> = [{ source: 'Base', value: baseValue, type: 'base' }]

      // Get modifiers from character state service
      const totalModifier = characterStateService.getTotalModifier(
        character.id,
        'stat',
        statName,
      )

      if (totalModifier !== 0) {
        breakdown.push({
          source: 'Modifiers',
          value: totalModifier,
          type: 'ongoing',
        })
      }

      const total = baseValue + totalModifier

      return {
        base: baseValue,
        modifier: totalModifier,
        total,
        breakdown,
      }
    },
    [character],
  )

  // Individual stats with modifiers
  const strength = useMemo(() => {
    return calculateStatWithModifiers(
      'strength',
      character?.attributes.strength || 0,
    )
  }, [character?.attributes.strength, calculateStatWithModifiers])

  const dexterity = useMemo(() => {
    return calculateStatWithModifiers(
      'dexterity',
      character?.attributes.dexterity || 0,
    )
  }, [character?.attributes.dexterity, calculateStatWithModifiers])

  const constitution = useMemo(() => {
    return calculateStatWithModifiers(
      'constitution',
      character?.attributes.constitution || 0,
    )
  }, [character?.attributes.constitution, calculateStatWithModifiers])

  const intelligence = useMemo(() => {
    return calculateStatWithModifiers(
      'intelligence',
      character?.attributes.intelligence || 0,
    )
  }, [character?.attributes.intelligence, calculateStatWithModifiers])

  const wisdom = useMemo(() => {
    return calculateStatWithModifiers(
      'wisdom',
      character?.attributes.wisdom || 0,
    )
  }, [character?.attributes.wisdom, calculateStatWithModifiers])

  const charisma = useMemo(() => {
    return calculateStatWithModifiers(
      'charisma',
      character?.attributes.charisma || 0,
    )
  }, [character?.attributes.charisma, calculateStatWithModifiers])

  // Computed values
  const hitPoints = useMemo(() => {
    if (!character) {
      return { current: 0, max: 0, percentage: 0 }
    }

    const current = character.hp.current
    const max = character.hp.max
    const percentage = max > 0 ? (current / max) * 100 : 0

    return { current, max, percentage }
  }, [character?.hp])

  const load = useMemo(() => {
    if (!character) {
      return { current: 0, max: 0, percentage: 0, status: 'light' as const }
    }

    const current = character.load.current
    const max = character.load.max
    const percentage = max > 0 ? (current / max) * 100 : 0

    let status: 'light' | 'normal' | 'heavy' | 'overloaded'
    if (percentage <= 33) status = 'light'
    else if (percentage <= 66) status = 'normal'
    else if (percentage <= 100) status = 'heavy'
    else status = 'overloaded'

    return { current, max, percentage, status }
  }, [character?.load])

  // Stat operations
  const updateBaseStat = useCallback(
    (stat: keyof Attribute, value: number) => {
      if (!character) return

      updateCharacter({
        attributes: {
          ...character.attributes,
          [stat]: value,
        },
      })
    },
    [character, updateCharacter],
  )

  const getStatModifier = useCallback(
    (stat: keyof Attribute): number => {
      const statValue = character?.attributes[stat] || 0
      return Math.floor((statValue - 10) / 2)
    },
    [character?.attributes],
  )

  const getStatTotal = useCallback(
    (stat: keyof Attribute): number => {
      switch (stat) {
        case 'strength':
          return strength.total
        case 'dexterity':
          return dexterity.total
        case 'constitution':
          return constitution.total
        case 'intelligence':
          return intelligence.total
        case 'wisdom':
          return wisdom.total
        case 'charisma':
          return charisma.total
        default:
          return 0
      }
    },
    [strength, dexterity, constitution, intelligence, wisdom, charisma],
  )

  // Modifier management
  const getTotalModifierForStat = useCallback(
    (stat: keyof Attribute): number => {
      if (!character) return 0
      return characterStateService.getTotalModifier(character.id, 'stat', stat)
    },
    [character],
  )

  const getModifierBreakdown = useCallback(
    (stat: keyof Attribute) => {
      switch (stat) {
        case 'strength':
          return strength.breakdown
        case 'dexterity':
          return dexterity.breakdown
        case 'constitution':
          return constitution.breakdown
        case 'intelligence':
          return intelligence.breakdown
        case 'wisdom':
          return wisdom.breakdown
        case 'charisma':
          return charisma.breakdown
        default:
          return []
      }
    },
    [strength, dexterity, constitution, intelligence, wisdom, charisma],
  )

  return {
    // Character reference
    character,

    // Individual stats with modifiers
    strength,
    dexterity,
    constitution,
    intelligence,
    wisdom,
    charisma,

    // Computed values
    hitPoints,
    load,

    // Stat operations
    updateBaseStat,
    getStatModifier,
    getStatTotal,

    // Modifier management
    getTotalModifierForStat,
    getModifierBreakdown,

    // Utility
    isLoading,
    error,
  }
}

/**
 * Hook for getting just the stat modifiers (for dice rolling)
 * Optimized for performance when only modifiers are needed
 */
export function useStatModifiers(characterId?: string) {
  const { character } = useCharacter(characterId)

  const modifiers = useMemo(() => {
    if (!character) {
      return {
        strength: 0,
        dexterity: 0,
        constitution: 0,
        intelligence: 0,
        wisdom: 0,
        charisma: 0,
      }
    }

    return {
      strength: Math.floor((character.attributes.strength - 10) / 2),
      dexterity: Math.floor((character.attributes.dexterity - 10) / 2),
      constitution: Math.floor((character.attributes.constitution - 10) / 2),
      intelligence: Math.floor((character.attributes.intelligence - 10) / 2),
      wisdom: Math.floor((character.attributes.wisdom - 10) / 2),
      charisma: Math.floor((character.attributes.charisma - 10) / 2),
    }
  }, [character?.attributes])

  return modifiers
}

/**
 * Lazy Hover System with Intersection Observer
 * Optimizes hover interactions by only enabling them when elements are visible
 * Prevents performance issues with large numbers of rollable elements
 */

import { useCallback, useEffect, useRef, useState } from 'react'

interface LazyHoverOptions {
  enabled?: boolean
  rootMargin?: string
  threshold?: number
  enabledDistance?: number // Distance in pixels to pre-enable hover before element enters viewport
}

interface HoverState {
  isVisible: boolean
  isHoverEnabled: boolean
  isHovered: boolean
}

export function useLazyHover({
  enabled = true,
  rootMargin = '50px',
  threshold = 0.1,
  enabledDistance = 100,
}: LazyHoverOptions = {}) {
  const elementRef = useRef<HTMLElement>(null)
  const observerRef = useRef<IntersectionObserver | null>(null)
  const [hoverState, setHoverState] = useState<HoverState>({
    isVisible: false,
    isHoverEnabled: false,
    isHovered: false,
  })

  // Intersection Observer callback
  const handleIntersection = useCallback(
    (entries: IntersectionObserverEntry[]) => {
      entries.forEach((entry) => {
        const isVisible = entry.isIntersecting
        const isNearViewport =
          entry.boundingClientRect.top < window.innerHeight + enabledDistance &&
          entry.boundingClientRect.bottom > -enabledDistance

        setHoverState((prev) => ({
          ...prev,
          isVisible,
          isHoverEnabled: isNearViewport,
        }))
      })
    },
    [enabledDistance],
  )

  // Set up intersection observer
  useEffect(() => {
    if (!enabled || !elementRef.current) return

    observerRef.current = new IntersectionObserver(handleIntersection, {
      rootMargin,
      threshold,
    })

    observerRef.current.observe(elementRef.current)

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect()
      }
    }
  }, [enabled, handleIntersection, rootMargin, threshold])

  // Hover event handlers - only work when enabled
  const handleMouseEnter = useCallback(() => {
    if (hoverState.isHoverEnabled) {
      setHoverState((prev) => ({ ...prev, isHovered: true }))
    }
  }, [hoverState.isHoverEnabled])

  const handleMouseLeave = useCallback(() => {
    if (hoverState.isHoverEnabled) {
      setHoverState((prev) => ({ ...prev, isHovered: false }))
    }
  }, [hoverState.isHoverEnabled])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect()
      }
    }
  }, [])

  return {
    elementRef,
    isVisible: hoverState.isVisible,
    isHoverEnabled: hoverState.isHoverEnabled,
    isHovered: hoverState.isHovered && hoverState.isHoverEnabled,
    hoverProps: hoverState.isHoverEnabled
      ? {
          onMouseEnter: handleMouseEnter,
          onMouseLeave: handleMouseLeave,
        }
      : {},
  }
}

// Hook for managing multiple lazy hover elements efficiently
export function useLazyHoverManager(options: LazyHoverOptions = {}) {
  const [elements, setElements] = useState<Map<string, HoverState>>(new Map())
  const observerRef = useRef<IntersectionObserver | null>(null)
  const elementsRef = useRef<Map<string, HTMLElement>>(new Map())

  const registerElement = useCallback((id: string, element: HTMLElement) => {
    elementsRef.current.set(id, element)

    setElements(
      (prev) =>
        new Map(
          prev.set(id, {
            isVisible: false,
            isHoverEnabled: false,
            isHovered: false,
          }),
        ),
    )

    if (observerRef.current) {
      observerRef.current.observe(element)
    }
  }, [])

  const unregisterElement = useCallback((id: string) => {
    const element = elementsRef.current.get(id)
    if (element && observerRef.current) {
      observerRef.current.unobserve(element)
    }

    elementsRef.current.delete(id)
    setElements((prev) => {
      const next = new Map(prev)
      next.delete(id)
      return next
    })
  }, [])

  const setHoverState = useCallback((id: string, isHovered: boolean) => {
    setElements((prev) => {
      const current = prev.get(id)
      if (!current || !current.isHoverEnabled) return prev

      const next = new Map(prev)
      next.set(id, { ...current, isHovered })
      return next
    })
  }, [])

  // Set up intersection observer
  useEffect(() => {
    if (!options.enabled) return

    const handleIntersection = (entries: IntersectionObserverEntry[]) => {
      entries.forEach((entry) => {
        // Find the element ID
        let elementId: string | null = null
        for (const [id, element] of elementsRef.current) {
          if (element === entry.target) {
            elementId = id
            break
          }
        }

        if (!elementId) return

        const isVisible = entry.isIntersecting
        const isNearViewport =
          entry.boundingClientRect.top <
            window.innerHeight + (options.enabledDistance || 100) &&
          entry.boundingClientRect.bottom > -(options.enabledDistance || 100)

        setElements((prev) => {
          const current = prev.get(elementId!)
          if (!current) return prev

          const next = new Map(prev)
          next.set(elementId!, {
            ...current,
            isVisible,
            isHoverEnabled: isNearViewport,
          })
          return next
        })
      })
    }

    observerRef.current = new IntersectionObserver(handleIntersection, {
      rootMargin: options.rootMargin || '50px',
      threshold: options.threshold || 0.1,
    })

    // Observe existing elements
    elementsRef.current.forEach((element) => {
      observerRef.current!.observe(element)
    })

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect()
      }
    }
  }, [options])

  const getElementState = useCallback(
    (id: string): HoverState | null => {
      return elements.get(id) || null
    },
    [elements],
  )

  const getHoverProps = useCallback(
    (id: string) => {
      const state = elements.get(id)
      if (!state?.isHoverEnabled) {
        return {}
      }

      return {
        onMouseEnter: () => setHoverState(id, true),
        onMouseLeave: () => setHoverState(id, false),
      }
    },
    [elements, setHoverState],
  )

  return {
    registerElement,
    unregisterElement,
    getElementState,
    getHoverProps,
    getStats: () => ({
      totalElements: elements.size,
      visibleElements: Array.from(elements.values()).filter((s) => s.isVisible)
        .length,
      hoverEnabledElements: Array.from(elements.values()).filter(
        (s) => s.isHoverEnabled,
      ).length,
      hoveredElements: Array.from(elements.values()).filter((s) => s.isHovered)
        .length,
    }),
  }
}

// Performance monitoring hook
export function useHoverPerformanceMonitor() {
  const [metrics, setMetrics] = useState({
    totalHoverElements: 0,
    activeHoverElements: 0,
    averageHoverEnableTime: 0,
    performanceScore: 100,
  })

  const startTime = useRef<number>(0)

  const trackHoverEnable = useCallback(() => {
    startTime.current = performance.now()
  }, [])

  const trackHoverDisable = useCallback(() => {
    if (startTime.current > 0) {
      const duration = performance.now() - startTime.current
      setMetrics((prev) => ({
        ...prev,
        averageHoverEnableTime: (prev.averageHoverEnableTime + duration) / 2,
      }))
    }
  }, [])

  const updateElementCounts = useCallback((total: number, active: number) => {
    setMetrics((prev) => {
      const performanceScore =
        total > 0 ? Math.max(0, 100 - (active / total) * 50) : 100

      return {
        ...prev,
        totalHoverElements: total,
        activeHoverElements: active,
        performanceScore,
      }
    })
  }, [])

  return {
    metrics,
    trackHoverEnable,
    trackHoverDisable,
    updateElementCounts,
  }
}

